window.READER_DATA={"title": "Yakan Islam Fikra", "slug": "yakan-islam-fikra", "pages": [{"n": 1, "paras": ["لمزيد من الكتب والأبحاث زوروا موقعنا مكتبة فلسطين للكتب المصورة", "فتحي يكن", "الإسلام فكرة وحركة وانقلاب", "مؤسسة الرسالة"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0001.png"}, {"n": 2, "paras": ["الإسلام فِكْرَة وَحَرَكَة وَانْقِلَاب", "فَتْحِي يَكَن", "مُؤَسَّسَة الرِّسَالَة"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0002.png"}, {"n": 3, "paras": ["فصل في أحكام المرتد", "المرتد هو الذي يقطع الإسلام بنية أو قول كفر أو فعل، سواء كان استهزاء أو عناداً أو اعتقاداً.", "ومن أتى بناقض من نواقض الإسلام، وجب عليه التوبة فوراً، والرجوع إلى الإسلام بالشهادتين، والإقلاع عما وقع فيه من كفر.", "قال الله تعالى: ﴿وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِ فَيَمُتْ وَهُوَ كَافِرٌ فَأُولَٰئِكَ حَبِطَتْ أَعْمَالُهُمْ فِي الدُّنْيَا وَالْآخِرَةِ ۖ وَأُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ﴾.", "فالردة تحبط العمل، وتوجب الخلود في النار إن لم يتب العبد منها قبل الموت.", "ومن أحكام المرتد:", "١- بطلان عقده للنكاح، فلا يحل له أن يمسك زوجته المسلمة أو الكتابية.", "٢- لا يرث ولا يورث، فلا يرث من أقاربه المسلمين، ولا يرثه أقاربه المسلمون.", "٣- لا يغسل ولا يصلى عليه ولا يدفن في مقابر المسلمين إذا مات على ردته.", "والواجب على ولي الأمر أو من ينوب عنه دعوة المرتد إلى التوبة، وإزالة الشبهة التي قد تكون عرضت له، فإن أصر على كفره، أقيم عليه حد الردة."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0003.png"}, {"n": 4, "paras": ["محتويات الكتاب", "الفصل الاول : الاسلام بين المبدأ والتطبيق *", "- شبهات حول الاسلام", "- عوامل نشوء الشبهات", "- خصائص المنهج الاسلامي", "- الاسلام بين القابلية التطبيقية والنظرية الخيالية .", "الفصل الثاني : الحركة الاسلامية بين الامس واليوم *", "- حاجة التشريع الى دولة", "- بين العمل الفردي والعمل الحركي", "- نشأة الحركة الاسلامية الأولى", "- قواعد التنظيم الحركي", "- منجزات الحركة الاسلامية الأولى"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0004.png"}, {"n": 5, "paras": ["- طلائع البعث الاسلامي الحديث", "- جذور الحركة الاسلامية الحديثة", "- لمحات من تاريخ الحركة الاسلامية الحديث . الفصل الثالث : الانقلابية بين الاسلام والاتجاهات الحديثة", "- جهل وتضليل", "- الاسلام مفهوم انقلابي", "- خصائص الانقلابية الاسلامية", "- الانقلابية في منهج الاتجاهات العصرية", "- الاهداف الكبرى لانقلابية الاسلام", "- الخطة الانقلابية", "- الطليعة المؤمنة", "- المناخ المناسب ."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0005.png"}, {"n": 6, "paras": ["بسم الله الرحمن الرحيم", "المقدمة", "الاسلام - يخوض اليوم معركة مصير ومن حقه على ابنائه والسائرين في دربه ان يذودوا عنه وينافحوا دونه بكل ما يملكون من امكانيات فكرية ومادية ومعنوية ... ومعركة المصير هذه ينبغي ان تستنفر اهل الايمان في كل مكان لسد الثغرات وحماية الجبهات التي يمكن ان يتسلل منها الى الاسلام خصومه واعداؤه ... ومسؤولية العاملين في الحقل الاسلامي - في هذه الفترة - مسؤولية ضخمة ودقيقة . وبقدر البذل يكون الجزاء وعلى قدر الجهد يأتي العطاء ..."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0006.png"}, {"n": 7, "paras": ["وهذا الكتاب ... صورة مصغرة للمعركة التي يخوضها الاسلام على جميع الجبهات ... وعرض سريع للدور الذي تضطلع به ( الحركة الاسلامية ) المعاصرة ... وجلاء لبعض الجوانب من تاريخها المشرق ...", "وهو كذلك كشف لخصائص الاسلام الفكرية والانقلابية مقارن بخصائص الحركات والاتجاهات العقائدية والسياسية الحديثة", "واني لأسأل الله تعالى ان تتحقق به الفائدة ويكتب فيه الاجر ... وعلى الله قصد السبيل ...", "والله اكبر ولله الحمد المؤلف"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0007.png"}, {"n": 8, "paras": ["الإسلام برهان بين المبدأ والتطبيق"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0008.png"}, {"n": 9, "paras": ["فصل في أحكام المرتد", "المرتد هو الذي يقطع الإسلام بنية أو قول كفر أو فعل، سواء كان استهزاء أو عناداً أو اعتقاداً.", "ومن أتى بناقض من نواقض الإسلام، وجب عليه التوبة فوراً، والرجوع إلى الإسلام بالشهادتين، والإقلاع عما وقع فيه من كفر.", "قال الله تعالى: ﴿وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِ فَيَمُتْ وَهُوَ كَافِرٌ فَأُولَٰئِكَ حَبِطَتْ أَعْمَالُهُمْ فِي الدُّنْيَا وَالْآخِرَةِ ۖ وَأُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ﴾.", "فالردة تحبط العمل، وتوجب الخلود في النار إن لم يتب العبد منها قبل الموت.", "ومن أحكام المرتد:", "١- بطلان عقده للنكاح، فلا يحل له أن يمسك زوجته المسلمة أو الكتابية.", "٢- لا يرث ولا يورث، فلا يرث من أقاربه المسلمين، ولا يرثه أقاربه المسلمون.", "٣- لا يغسل ولا يصلى عليه ولا يدفن في مقابر المسلمين إذا مات على ردته.", "والواجب على ولي الأمر أو من ينوب عنه دعوة المرتد إلى التوبة، وإزالة الشبهة التي قد تكون عرضت له، فإن أصر على كفره، أقيم عليه حد الردة."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0009.png"}, {"n": 10, "paras": ["ليس من قبيل المبالغة القول بأن التحديات ( الفكرية والسياسية والغوغائية ) التي يتعرض لها الاسلام في العصر الحديث تفوق - ضخامة وشراسة - كل التحديات التي واجهتها الحركات الاخرى مجتمعة ... ولو تعرض لمثل ما تعرض له الاسلام نظام آخر من الانظمة الوضعية لعفى اثره ، وانطوى ذكره ولم يعد له في واقع الحياة ادنى وجود. ولكنه الاسلام... المنهج الالهي الخالد الذي يستعصي بخصائص البقاء على معاول الهدم ، ويخرج من كل صراع قوياً منتصراً ، مؤكداً على الزمن ابديته التي جعلها الله إحدى صفاته المميزة حين قرر ( انا نحن نزلنا الذكر وإنا له لحافظون ) اتهم الاسلام بالرجعية ... واعتبر متهموه الدعوة اليه عودا بالبشرية الى الوراء وتخلفاً عن ركب الحضارة والمدنيه"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0010.png"}, {"n": 11, "paras": ["الاف السنين . جاء في الموسوعة السوفياتية الكبيرة وفي الصفحة ٦١٥ - ٦١٩ من الجزء الثاني عشر ( ان الاسلام لعب على الدوام كغيره من الاديان الاخرى دوراً رجعياً ... وكان دائماً اداة في ايدي الطبقات الرجعية المستغلة لأرهاق الطبقات العاملة ، واداة للاستعمار الاجنبي الرامي الى استعباد شعوب الشرق ... ان السنة والقرآن كليهما يبرران النظام الطبقي والاستغلال . الخ )", "ثم جاء من يعتبر الاسلام تجربة من التجارب التي مرت بالحياة العربية ليس الا . وانه قد استنفد اغراضه وليس لديه مقومات البقاء والنماء والعطاء ... فقد جاء في الصفحة ٥١ من كتاب ( في سبيل البعث ) لميشيل عفلق قوله ( فهذه الامة التي افصحت عن نفسها وعن شعورها بالحياة افصاحا متعددا متنوعا ، في تشريع حمورابي ، وشعر الجاهلية - ودين محمد وثقافة المأمون فيها شعور واحد ... الخ )", "واتهم الاسلام بانه نظرية ( تجريدية ) وفلسفة ( مثالية ) غير قابلة للتطبيق", "وهكذا ذهب اعداء الاسلام في اتهاماتهم مذاهب شتى ( يريدون ليطفئوا نور الله بأفواههم والله متم نوره ولو كره الكافرون ... )"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0011.png"}, {"n": 12, "paras": ["عوامل نشوء هذه الشبهات", "لقد تسبب وساعد على نشوء مثل هذه الشبهات وقيام امثال هذه الحملات المسعورة من التضليل والتشكيك في وجه الاسلام عوامل كثيرة منها :", "١ - غيبة الوجود ( الحركي ) للاسلام عن قيادة الامة فترة طويلة من الزمن . مما ادى الى تطاول خصومه في نجوة من وجود حكومة اسلامية تدافع دونه وترد عنه شائعات الحاقدين.", "٢ - اصابة الامة ( فكريا ونفسيا ) بلوثات مادية جانحة من تأثير الحضارة الغربية الغازية ...", "٣ - تسلل الفكر اليساري ( الماركسي ) الى المجتمع الاسلامي يسوق امامه فيضاً من التصورات والآراء والطعون بكل فكرة ( دينية ) على الاطلاق ، نتيجة لردة الفعل التي احدثتها انحرافات الكنيسة الاوروبية عن اطار المسيحية الروحي ...", "٤ - جهل المسلمين بحقيقة دينهم وخصائص اسلامهم وآفاق شريعتهم ، مما جعلهم لقمة سائغة للاتجاهات والمذاهب المادية التي غزت العالم الاسلامي في مطلع القرن العشرين . هذه الاسباب وغيرها عملت - على الزمن - على عزل الاسلام عن الصراع الحياتي الذي تخوضه الامة ... والبسته ثوبا كهنوتيا ليس منه... وبالتالي أدت الى نشوء اجيال من"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0012.png"}, {"n": 13, "paras": ["المسلمين لم تطلع على الاسلام الا من زوايا مظلمة زادتها منه نفرة وانفلاتا.. حتى اصبح الاسلام بأفكاره واخلاقه ومبادئه في واد واصبح المسلمون (المنتسبون اليه) في واد اخر لا يمت اليه بصلة من الصلات على الاطلاق ...", "ولو ادرك المسلمون ان الاسلام : صيحة الحرية في وجه العبودية وصيحة المساواة في وجه الطبقية وصيحة العدالة الاجتماعية في وجه الاقطاع والرأسمالية", "لو ادرك المسلمون ان دينهم هذه خصائصه ومبادئه لما وجدت الاتجاهات الاشتراكية والشعوبية منفذا الى بلاد الاسلام ، ولما اصبحت المجتمعات الاسلامية سوقا ( عامة ) لعرض المبادىء المستوردة والشعارات المزيفه ..", "وليسمع شباب الاسلام والمثقفون منهم بوجه اخص ما يقوله ( اللورد استانلي ) وكان نصرانيا فأسلم وكان يتحدث عن الاسباب والعوامل التي حدت به الى اعتناق الاسلام . قال استانلي ( او اغمط الفضل اهله . اواجحد الله وعلمه.. انا مسلم ... رأيت اثر الاسلام وقدرته في نفسي حق قدره .. وهو عندي عزيز لأني رأيت الفرق بينه وبين الاديان المنسوخة . ولأني رضيت به بعد بحث واجتهاد ، فلا اقبل به بديلا . انا مسلم اهزأ بكل ما يحيط بي من مظاهر المدنية .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0013.png"}, {"n": 14, "paras": ["فصيحها الحق من كتاب الله وقرآنه .. وباطلها المذاع لا يلبث أن تبرهن الايام على بطلانه .. )", "خصائص المنهج الاسلامي", "ان الاسلام يمتاز بخصائص ذاتية هي فواصل جذرية وفوارق اصيلة بينه وبين الاتجاهات والمذاهب الحديثة ..", "الحاكمية لله", "فالحاكمية في المنهج الاسلامي لله ... لا لفرد ، ولا لحزب ، ولا لشعب . فلا ديكتاتورية لفرد ... ولا تسلط لحزب ... ولا حاكمية لشعب في تشريع الاسلام . والحقيقة ان معظم المظالم الاجتماعية والاقتصادية ، ومظاهر الاستبداد السياسي منشؤها خضوع الحاكمية لتشريع زمني وضعي ولسلطة بشرية ... فالنظام الديمقراطي يجعل الحاكمية للشعب ... ويجعله مصدر السلطات ... منه واليه يعود كل امر ... وبذلك يكرس التميع ( الفردي ) والانتفاخ ( الشخصي ) مما لا يتحقق معه"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0014.png"}, {"n": 15, "paras": ["هيبة في الحكم او أمن وسلام في المجتمع .. ان شعور الفرد في ظل النظام الديمقراطي بأنه مصدر القوانين والتشاريع ينمي فيه بواعث الاستهتار بالقوانين والتشاريع ... ويعطيه من اسباب السطوة ما يجعله قادرا بنفوذه الشخصي والمادي على تسخير السلطة لمصالحه ورغباته .. وبالتالي يمنحه حق التلاعب بالقوانين ووضعها بما يتلاءم مع اهوائه واغراضه ...", "يقول ( مارتن دودج ) في كتابه ( اعرف مذهبك ) صفحة ١٨ في معرض حديثه عن الديمقراطية : ( وفكرة الديمقراطية تتلخص في ان يحكم الناس انفسهم دون ان يكونوا رعايا . ذلك ان الناس لهم المقام الاول والصدارة . ثم تليهم في المرتبة الثانية السلطة الحاكمة . وفي ظل النظام الديمقراطي يحكم المجتمع نفسه من اجل نفسه .. )", "اما النظام الشيوعي ، فانه يكرس حاكمية ( الحزب الواحد ) للامة بأسرها... وبذلك يعطي الحزب نفسه حق سن القوانين واستصدار التشاريع بما يكفل له البقاء والسيطرة في الحكم .. وهو بذلك نظام سياسي يقبض بمقتضاه ( الحزب ) على زمام السلطة في بلد يخضع افراده عموما لما يفرض عليهم وعلى شؤون حياتهم من اجراءات ..", "فالحزب الشيوعي في ( روسيا ) مثلا ، هو الحزب السياسي الوحيد والحاكم ... ومع ذلك فانه لا يمثل الشعب الروسي"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0015.png"}, {"n": 16, "paras": ["اصدق تمثيل اذ يبلغ عدد اعضائه ستة ملايين فقط من اصل ١٨٠ مليونا ، وهي كما نرى نسبة ضئيلة جدا .. وبهذا لا يمكن ان تكون حاكمية ( الحزب الواحد ) في أي نظام من انظمة الحكم مصدر استقرار وعدالة ومساواة . طالما ان الذين في ايديهم السلطة يخضعون كل شيء لمصالحهم الشخصية والحزبية .", "وبين هذين الاتجاهين يقوم ( المنهج الاسلامي ) فوق قواعد تشريعية يخضع لها الحاكم والمحكوم على حد سواء .. وينصاع لها الكبير والصغير دونما تمايز او تخصيص .. فالحاكمية في النظام الاسلامي ليست لشعب - كما هو الشأن في النظام ( الديمقراطي ) . كما انها ليست لحزب كما هو الحال في النظام ( الشيوعي ) وسائر الانظمة ( الاشتراكية ) .. وهي كذلك ليست لفرد كما هو الامر في النظم ( الديكتاتورية ) وانما هي ( لله ) خالق الكون ومالكه . وهذا ما يقرره الدستور الاسلامي في كثير من آياته : ( ان الحكم الا الله ) ( وما اختلفتم فيه من شيء فحكمه إلى الله ) ( انا انزلنا اليك الكتاب بالحق لتحكم بين الناس بما اراك الله ) .", "والاسلام يحقق هذه الحاكمية الربانية عن طريق ( قانون الهي ) يتضمن الاحكام التي جاء بها القرآن الكريم وفسرتها وفصلتها سنة رسول الله صلى الله عليه وسلم ... فالاسلام منهج متفرد في خصائصه .. لم تضع احكامه"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0016.png"}, {"n": 17, "paras": ["ونظمه وتشريعاته اهواء حاكم او مصلحة حزب .. وانما وضعتها عدالة السماء ... فلا تمييز ولا محاباة ، ولا انانية ولا تحكم ، ولا حزبية ، ولا سطوة وانما الجميع امام شرع الله سواء ...", "عدالة لا تعرف ظلما ولا عنتا ولا تفاضل .. ومساواة تطبق على الجميع من غير محسوبيات او استثناءات وهاكم بعض الشواهد من دستور الله الخالد : ( يا ايها الذين امنوا كونوا قوامين لله شهداء بالقسط ولا يجرمنكم شنآن قوم على الا تعدلوا اعدلوا هو اقرب للتقوى واتقوا الله ان الله خبير بما تعملون)(وان احكم بينهم بما انزل الله ولا تتبع اهواءهم واحذرهم ان يفتنوك عن بعض ما انزل الله اليك ) ( فاحكم بينهم بما انزل الله ولا تتبع اهواءهم عما جاءك من الحق )", "وروى ان امرأة من بني مخزوم سرقت فقالت قريش ، من يكلم فيها رسول الله صلى الله عليه وسلم اى ليضع عنها الحد . فلم يجدوا الا ( اسامة بن زيد ) حب رسول الله صلى الله عليه وسلم يقوى على ذلك . فلما كلم اسامة رسول الله بذلك ، قال رسول الله غاضبا : ( اتشفع في حد من حدود الله يا اسامة ) ثم قام وخطب الناس قائلا ( ايها الناس انما ضل من كان قبلكم انهم كانوا اذا سرق الشريف تركوه . واذا سرق الضعيف فيهم اقاموا عليه الحد . وايم الله لوان فاطمة بنت محمد سرقت لقطع محمد يدها .. )"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0017.png"}, {"n": 18, "paras": ["ومن وصايا عمر بن الخطاب رضي الله عنه لسعد بن ابي وقاص ( ان الله ليس بينه وبين احد نسب الا طاعته . فالناس شريفهم ووضيعهم في ذات الله سواء ) .. وفي وصيته للخليفة من بعده يقول ( اجعل الناس عندك سواء . لا تبال على من وجب الحق . ثم لا تأخذك في الله لومة لائم . واياك والاثرة والمحاباة فيما ولاك الله .. )", "الشمول لا الجزئية", "ومن خصائص المنهج الاسلامي شموله وكليته .. فالاسلام ليس تصورا ( عقيديا ) فحسب ... ولا دينا ( عباديا روحيا ) وكفى ... ولا نظاما اقتصاديا واجتماعيا وسياسيا مجردا .. ولكنه منهج حياة . يجمع الى رقة ( التوجيه ) دقة ( التشريع ) . وإلى جلال ( العقيدة ) جمال ( العبادة ) والى إمامة ( المحراب ) قيادة ( الحرب ) .", "ان المنهج الاسلامي لم يكن ردة فعل لسوء اوضاع اقتصادية ليكون نظاما اقتصاديا شأن الماركسية وسائر المذاهب الاشتراكية .. كما انه ليس مدرسة روحانية شأن المسيحية .. ان الاسلام منهج متكامل الجوانب شامل النظرة.. فيه تنظيم علاقة الفرد بنفسه .. وعلاقته باسرته . وعلاقته بمجتمعه. وعلاقة مجتمعه به ... وفيه بيان للاصول والقواعد التي تقوم", "- ١٧ - الاسلام - ٢"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0018.png"}, {"n": 19, "paras": ["عليها النظم والقوانين التي تحكم سير المجتمع والناس وفق نظرة الاسلام للكون والانسان والحياة ...", "يقول جيبون : القرآن مسلم بانه الدستور الاساسي . ليس لأصول العقيدة فحسب . بل وللاحكام الجنائية والمدنية . وللشرائع التي عليها مدار حياة النوع الانساني وترتيب شؤونه . وبعبارة اخرى هو القانون العام للعالم الاسلامي . فهو قانون شامل للقوانين المدنية والتجارية والحربية والقضائية والجنائية )", "الفطرية لا التطرف او المثالية", "ومن خصائص المنهج الاسلامي انه دين الفطرة ... اعترف للانسان بحاجاته الروحية والعضوية . وقيمة تقييما انسانيا ، مراعيا في ذلك نوازعه الفطرية كلها ، محققاً التناسق والتوافق بينها جميعا ...", "فالاسلام لم ينظر إلى الانسان نظرة ( مادية مجردة ) لا تتعدى هيكله الجسدي ومتطلباته الغريزية شأن الشيوعية وسائر المذاهب المادية ... في الوقت الذي لم يحرمه حقوقه البدنية وحاجاته البشرية .", "فلم يكن الاسلام ( ابيقوريا ) (١) في اطلاقه للغرائز", "(١) نسبة الى الفلسفة التي وضعها ابيقور عام ٣٤٣ ق.م والتي تعتبر اللذه اساس الاخلاق - وانها وحدها غاية الانسان - وهي وحدها الخير ."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0019.png"}, {"n": 20, "paras": ["والشهوات من غير تنظيم ولا تكييف... كما لم يكن (رواقيا) (١) في فرض المثالية الخيالية ، واعدام المتطلبات الغريزية في الانسان .", "وفطرية الاسلام جسدت في مبادئه ( النظرة الواقعية ) وافردته بخصائص التوفيق والتنسيق بين المادة والروح . وهذا ما ينطق به مدلول الآية الكريمة ( لا يكلف الله نفسا الا وسعها لها ما كسبت وعليها ما اكتسبت ) ويقول الشهيد سيد قطب في تفسير هذه الآية : ( انها العقيدة التي تعترف بالانسان انسانا لا حيوانا ولا ملكا ولا شيطانا .. تعترف به كما هو بكل ما فيه من ضعف وكل ما فيه من قوة . وتأخذه وحدة مؤلفة من جسد ذي نوازع ، وعقل ذي تقدير ، وروح ذي اشواق . وتفرض عليه من التكاليف ما يطيق . وتراعي في التنسيق بين التكليف والطاقة بلا مشقة ولا اعنات (٢)", "الاطمئنان العقيدي لا القلق الوجودي", "ومن خصائص المنهج الاسلامي انه عرف (الانسان) على نفسه وسر خلقه وسبب وجوده ... فحل بذلك عقدة من اخطر العقد في الحياة البشرية ..", "(١) نسبة الى الفلسفة التي وضعها زينو القبرصي عام ٣٤٢ ق.م والتي تعتبر الشهوة شرا محضا يجب ابادته ..", "(٢) تفسير في ظلال القرآن للشهيد سيد قطب"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0020.png"}, {"n": 21, "paras": ["لم يترك الاسلام الانسان في الكون وحيدا بلا عماد .. حائرا من غير هدى .. يجابه مصيره بمفرده ... ويحدد طريقه لوحده .. ويحكم نفسه بنفسه ..", "لقد اجاب الاسلام على كل الاسئلة التي طرحها ( الوجوديون ) قديما وحديثاً والتي ارادوا من ورائها التفلت من كل القيود والحدود ليعيشوا احرارا كما يزعمون وهم في الحقيقة ( عبيد ) واكثر من عبيد ..", "فالاسلام لم يعتبر ( الوجود ) بلا غاية كما يزعم ( سارتر ) ولم يعتبره وجودا ( سخيفا ) في عالم لا معقول .. ولم يعتبر ان الانسان موجود فيه لا اكثر ولا اقل . لا يعرف من اين اتى... ولا الى اين هو ذاهب ... كذلك لم يعتبر الانسان مسيرا بدون ارادة تسوقه الطبيعة كالحيوان ..", "بل ان الاسلام جعل للانسان عقلا يفكر به ويستفتيه ، وارادة يتحرك بها كيفما شاء واني شاء ... وجعل لخلقه سببا لوجوده وللحياة الانسانية غاية ..", "خلق الانسان ليبلوه فيما آتاه ويخبره فيما اعطاه ايكفر ام يشكر ( انا خلقنا الانسان من نطفة امشاج نبتليه فجعلناه سميعا بصيرا . انا هديناه السبيل اما شاكرا واما كفورا )", "وطالبه بتسخير نفسه واعضائه ودفع غرائزه وميوله في طريق الخير ضمانا لعمارة الارض ، وتحقيقا لرسالة الاستخلاف : ( وهو الذي انشأ لكم السمع والابصار والافئدة"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0021.png"}, {"n": 22, "paras": ["قليلا ما تشكرون . وهو الذي درأكم في الارض واليه تحشرون . الى قوله : افحسبتم انما خلقناكم عبثا وانكم الينا لا ترجعون . فتعالى الله الحق لا اله الا هو رب العرش الكريم). فالانسان في الاسلام صاحب رسالة يعمل على ادائها .. وله غاية يسعى للوصول اليها .. انه يدرك ان حياته رحلة ينبغي ان يقطعها وفق الخط الالهي الذي يضمن له السعادة في الدنيا ، والنعيم الابدي في الآخرة ( من عمل صالحا من ذكر او انثى وهو مؤمن فلنحيينه حياة طيبة ولنجزينهم اجرهم بأحسن ما كانوا يعملون ... )", "الانقلابية الجذرية لا الترقيع", "ومن خصائص الاسلام أنه منهج انقلابي جذري .. فهو يرفض ارباع الحلول وانصافها . ولا يستسيغ التعايش مع الجاهلية ، ويأبى الترقيع ... ولقد صدع الاسلام في عهد النبوة كل محاولة لمساومة اصحابه واستدراجهم لقبول بعض الحلول او التنازل عن بعض الحق .. فهذه قريش تقترح على محمد ان يعبد الهتها شهرا لتعبد الهه شهرا اخر فينزل القرآن الكريم بالموقف الحاسم من امثال هذه المساومات فيقول ( قل : يا ايها الكافرون لا اعبد ما تعبدون ولا انتم عابدون ما اعبد ولا انا عابد ما عبدتم ولا"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0022.png"}, {"n": 23, "paras": ["انتم عابدون ما اعبد ، لكم دينكم ولي دين .. وجاء عتبة بن ربيعة يوما الى رسول صلى الله عليه وسلم يعرض عليه العروض السخية .. يعرض عليه الملك والمال والسلطان على ان يترك الامر الذي جاء به ويتخلى عن الاسلام. لكن محمداً صلى الله عليه وسلم التفت اليه مستعليا بايمانه معتزا باسلامه قائلا ( ما جئتكم بما جئتكم به اطلب اموالكم ولا الشرف فيكم ولا الملك عليكم . ولكن الله بعثني اليكم رسولا . وانزل كتابا . وامرني ان اكون لكم بشيرا ونذيرا . فان تقبلوا مني ما جئتكم به فهو حظكم في الدنيا والآخرة . وان تردوه علي اصبر لأمر الله حتى يحكم الله بيني وبينكم )", "الاسلام بين القابلية التطبيقية والنظرية الخيالية", "قد يكون من نافلة الكلام ان نقول ان البشرية لم تعرف في مدار التاريخ منهجا ( واقعي ) الخصائص كالاسلام .. فهو المنهج ( الوحيد ) الذي غير مجرى الحياة الانسانية ، واحدث في المجتمع البشري انقلابا جذريا شاملا قوض كل الافكار وكل الاخلاق وكل المعتقدات الجاهلية .. فالمنهج الاسلامي تجاوز نطاق النظريات ( التجريدية ).."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0023.png"}, {"n": 24, "paras": ["وتجسدت مبادئه واقعا حياتيا عاشه الناس وحفظه التاريخ ونطقت به الشواهد والاحداث ..", "من الشواهد التطبيقية في الاسلام :", "اولا - في نطاق العقيدة", "كان مبدأ ( لا اله الا الله ) دفعة العقيدة في قلوب الناس ، ومحرك الثورة الاصيل في نفوسهم ، ورمز انخلاعهم من ضلالات الجاهلية وأوضارها وانصهارهم في بوتقة الدين الجديد ..", "وكان الجذوة المتقدة التي حررت الانسان من عبودية الاصنام ، و كرمته عن اتخاذ الناس اربابا من دون الله ، والزمته افراده سبحانه بالربوبية والالوهية والخضوع والحاكمية ..", "فلم تكن ( لا اله الا الله ) شعارا تتحرك به الالسن من غير وعي ، او تردده الشفاه بدون ادراك .. وانما كان هتافا ربانيا يحدو القلوب الى السماء ، ويشدها نحو العلاء ، فتمتليء بقوة الله قوة .. وتحس في وصاله طمأنينة .. وتغدو بجواره عزيزة كريمة ..", "بهذا الامتلاء العقيدي والعبق الايماني كان العربي بعد الاسلام يقف امام طواغيت فارس والروم يدعوهم الى الاسلام"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0024.png"}, {"n": 25, "paras": ["باعتزاز ، ويبين تعاليمه بجرأة.. ثم يحذرهم عاقبة جحودهم وكفرانهم ، ويخيرهم بين الجزية والحرب .. ذكرت كتب التاريخ (١) انه قبيل معركة ( القادسية ) طلب رستم قائد الفرس من المسلمين ان يرسلوا اليه وفودا ورسلا منهم ، ليباحثهم ويباحثونه ، ويفاوضهم ويفاوضونه. فندب المسلمون فيمن ندبوا ( المغيرة بن شعبة ) ليكون سفيرهم الى رستم .. فلما وصل اليهم وهم على زيهم وبسطهم ( أدنى ) من مجلس رستم .. جاء وجلس معه على سريره .. فغضب وأمر بانزاله عن السرير .. فالتفت المغيرة اليهم قائلا ( اني لم ار اسفه منكم .. اننا معشر المسلمين لا يستعبد بعضنا بعضا .. فظننتكم كذلك .. وكان أحسن بكم ان تخبروني ان بعضكم ارباب بعض .. مع اني لم آتكم ، وانما دعوتموني. فقد علمت انكم مغلوبون ولن يقوم لكم ملك على هذه السيرة ..", "وتكلم رستم فعظم من شأن فارس ثم قال : ( كانت عيشتكم سيئة .. وكنتم تقصدوننا في الجدب فنردكم بشيء من التمر والشعير .. ولم يحملكم على ما صنعتم الا ما بكم من جهد .. فنحن نعطي لأمير كم كسوة وبغلا والف درهم .. وكل رجل منكم حمل تمر ، وتنصرفون ، فلست اشتهي قتلكم .. )", "(١) تاريخ ابن خلدون - المجلد الثاني - القسم الرابع .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0025.png"}, {"n": 26, "paras": ["فلم يكن من المغيرة الا ان التفت اليه قائلا ( اما الذي وصفتنا به من سوء الحال والضيق فنعرفه ولا ننكره .. والدنيا دول .. والشدة بعدها رخاء .. ولو شكرتم ما اتاكم الله لكان شكركم قليلا على ما اوتيتم .. وقد اسلمكم الله بضعف الشكر الى تغير الحال .. وان الله بعث فينا رسولا يدعونا الى كذا ، فان ابيتم فأمر اهون من ذلك فهو الجزية ، فان ابيتم فالمناجزة).", "ثانيا - في نطاق العبادة", "والعبادات في الاسلام ليست طقوسا جامدة ، أو مراسيم ميتة لاهدف لها ولا غاية .. بل ان الاسلام ارادها ( مدرسة ) للتربية ( ومصنعا ) للاخلاق والمثل .. ارادها معراجا تسمو به النفوس وتحلق .. ومصفاة تصفو بها الارواح وتزكو .. فالاسلام يحرص من عباداته على نتائجها وآثارها .. ويحاسب على مدى التفاعل بها فضلا عن فرضية ادائها .. فالمدلول التطبيقي والهدف العملي لمبدأ ( الصلاة ) ان تنهى صاحبها عن الفحشاء والمنكر .. وانه لا قيمة للصلاة - عند الله - ما لم تؤد هذا الغرض فقال تعالى ( ان الصلاة تنهى عن الفحشاء والمنكر ) وقال الرسول صلى الله عليه وسلم ( من لم تنهه صلاته عن الفحشاء والمنكر لم يزدد من الله الا بعدا (١) )", "(١) رواه الطبراني"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0026.png"}, {"n": 27, "paras": ["وقال ( كم من قائم حظه من صلاته التعب والنصب (١) ) وقال ( ليس للعبد من صلاته الا ما عقل منها ) والمدلول التطبيقي والهدف العملي لمبدأ ( الصوم ) ترويض النفس وسائر الاعضاء على الطاعة ، وانه لا ثواب لمن صام بطنه وافطر فرجه .. او صامت معدته عن الطعام وافطرت جوارحه على البغي والفحش والفجور .. وهذا ما يؤكده الاسلام في احاديث كثيرة للرسول صلى الله عليه وسلم يقول فيها ( انما الصوم جنة ، فاذا كان احدكم صائما فلا يرفث ولا يجهل ، وان امرؤ قاتله او شاتمه فليقل اني صائم اني صائم ) ويقول ( كم من صائم ليس له من صومه الا الجوع والعطش", "(٢) ويقول : ( من لم يدع قول الزور والعمل به فليس لله حاجة في ان يدع طعامه وشرابه ) . وجاء في الخبر ( ان امرأتين صامتا على عهد رسول الله صلى الله عليه وسلم فأجهدهما الجوع والعطش من آخر النهار ، حتى كادتا ان تتلفا . فبعثتا الى رسول الله صلى الله عليه وسلم يستأذنانه في الأفطار ، فأرسل اليهما قدحا وقال : قل لهما قيئا فيه ما اكلتما . فجاءت احداهما نصفه دما عبيطا ولحما غريضا .. وجاءت الاخرى مثل ذلك حتى ملأتاه. فعجب الناس من ذلك . فقال الرسول صلى الله عليه وسلم : هاتان صامتا عما احل الله لهما وافطرتا على ما", "(١) اخرجه النسائي", "(٢) اخرجه النسائي"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0027.png"}, {"n": 28, "paras": ["حرم الله تعالى عليهما .. فعدت احداهما الى الأخرى فجعلتا تغتبان الناس ، فهذا مما اكلتا من لحومهم (١) ) وهكذا تستهدف فلسفة العبادة في الاسلام تحقيق الاثر الفعلي وحصول التحول الكيفي في حياة الناس ..", "ثالثا - في نطاق التشريع", "كذلك القول في القواعد الاساسية التي يقوم عليها التشريع الاسلامي .. فانها تمتاز بقابليتها الاصلية واستعدادها الفطري للتطبيق . فالتشريع الاسلامي ليس كسائر المشاريع المسطرة في بطون الكتب .. البعيدة عن صميم حياة الناس .. بل ان نزعته التطبيقية وخصائصه التنفيذية تجعله منهجا ثوريا وحركيا وانقلابيا فيه كل امكانيات الثورة وكل متطلبات الحركة وكل حاجات الانقلاب .. فمن الشواهد التطبيقية لمبدأ ( المساواة ) في الاسلام .. ان رسول الله صلى الله عليه وسلم قلد اسامة بن زيد إمرة الجيش الاسلامي - وهو ابن عبد رقيق - وفي الجيش كبار الصحابة. وان بلالا الحبشي بلغ في الاسلام مقاما عظيما وشاءواً كبيرا جعل عمر بن الخطاب رضي الله عنه اذا ذكره يقول ( أبو", "(١) اخرجه احمد"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0028.png"}, {"n": 29, "paras": ["بكر سيد نا واعتق سيدنا ) .. وانه لما خرج المسلمون لفتح مصر .. رغب المقوقس في المفاوضة .. فارسل اليهم وفدا ليعلم ما يريدون .. ثم طلب منهم ان يبعثوا اليه وفدا منهم .. فشكل عمرو بن العاص ( قائد الجيش آنذاك ) وفدا قوامه عشرة من المسلمين برئاسة عبادة بن الصامت ، وكان شديد السواد طويلا ...", "ولما دخل الوفد على المقوقس ، تقدمهم عبادة .. فابى المقوقس ان يكلمه رجل اسود .. وقال لمن معه : نحوا عني هذا الاسود ، وقدموا غيره يكلمني . فقال الوفد جميعاً : ان هذا الاسود افضلنا رأيا وعلما .. وهو سيدنا وخيرنا والمقدم علينا .. وانما نرجع الى قوله ورأيه .. وقد امره الامير دوننا بما امره . وامرنا ان لا نخالف رأيه وقوله ..", "فقال لهم المقوقس : وكيف رضيتم ان يكون هذا الاسود افضلكم ، وانما ينبغي ان يكون دونكم ؟ قالوا : كلا - إنه وان كان اسود كما ترى . فانه من افضلنا موضعا ، وافضلنا سابقة وعقلا ورأيا .. وليس ينكر السواد فينا .", "ومن الشواهد التطبيقية لمبدأ ( العدالة ) : ان عمر بن الخطاب رضي الله عنه كان يفرض لجميع المسلمين عطاء من بيت المال ويقول : والله ما احد احق بهذا المال من احد .. وما انا احق به من احد ... والله ما من المسلمين من احد الا وله في هذا المال نصيب . ولكنا على منازلنا في كتاب الله"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0029.png"}, {"n": 30, "paras": ["تعالى .. فالرجل وبلاؤه في الاسلام .. والرجل وقدمه في الاسلام .. والرجل وحاجته .. والله لئن بقيت لهم ليأتين الراعي بجبل صنعاء حظه من هذا المال وهو يرعى غنمه )", "واذا كان الرسول صلى الله عليه وسلم قد اعلن مبدأ العدالة في كلام جامع قال فيه ( لا تقدّس امة لا يقضى فيها بالحق .. ولا يأخذ الضعيف حقه من القوى ) . فقد اصبح القول عملا والمبدأ واقعا في حياة المسلمين وعلاقتهم ومعايشهم. وتحقق فيهم قول الله تعالى ( يا ايها الذين آمنوا كونوا قوامين بالقسط ، شهداء لله ولو على انفسكم أو الوالدين والاقربين ، ان يكن غنيا او فقيرا فالله اولى بهما ، فلا تتبعوا الهوى ان تعدلوا )", "بهذه النماذج ( التطبيقية ) كانت تتجسد مبادىء الاسلام التشريعية في حياه المسلمين .. لم تكن شعارات للاستهلاك والمتاجرة .. كما انها لم تكن نظريات ومثاليات مجردة عاجزة عن التطبيق .. عارية عن التصديق ..", "رابعا - في نطاق الواقع", "كذلك فان قيام المجتمع الاسلامي في عهد النبوة واستمراره زمنا ليس بالقصير دليل حاسم على قابلية الاسلام للتطبيق ..."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0030.png"}, {"n": 31, "paras": ["يقول ( توماس كارليل ) : ما كاد الاسلام يظهر حتى احترقت فيه وثنيات العرب ، وجدليات النصرانية .. وكل ما لم يكن بحق فانه حطب جاف اكلته نار الاسلام ، فذهب والنار لم تذهب .. ولقد اخرج الله العرب بالاسلام من الظلمات الى النور .. واحيا به منها امة خاملة ، وارضا هامدة ، لا يسمع لها صوت ، ولا تحس فيها حركة منذ بدء العالم . فأرسل الله لهم نبيا بكلمة من لدنه . ورسالة من قبله .. فاذا الحمول شهرة .. والغموض قد استحال نباهة ، والضعة رفعة ، والضعف قوة ، والشرارة حريقا وسع نوره الانحاء ، وعم ضوءه الارجاء ، وعقد شعاعه الشمال بالجنوب ، والمشرق بالمغرب .. وما هو الا قرن بعد هذا الحادث ، حتى صار لدولة العرب رجل في الهند ، ورجل في الاندلس ، .. واشرقت دولة الاسلام حقبا عديدة ودهورا مديدة ، بنور الفضل والنبل ، والمروءة والبأس ، والنجدة ورونق الحق والهدى على نصف المعمورة .. )", "الاتجاهات الحديثة والفشل التطبيقي :", "ولو تخطينا الاسلام الى سواه من الاتجاهات والمبادىء الفكرية والسياسية « الوضعية » .. لرأينا انها لا تزال تخبط في مجالات التطبيق خبط عشواء .. فلا تكاد تستوي حتى تتعثر .. ولا توشك ان تتقدم حتى تتقهقر .. ويكفي انها لم تقدم -"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0031.png"}, {"n": 32, "paras": ["حتى الان - بين يدي الواقع ما يؤكد قابليتها التطبيقية .. بل ان الفشل عنوان تجاربها ومحاولاتها الكثيرة المستمرة ..", "أ - فشل الاتجاه الماركسي", "يلاحظ المتتبع للتطورات الفكرية والسياسية في العالم اثار التخبط التي يعانيها الاتجاه الماركسي في مجالات التطبيق .. وبخاصة في ارض التجربة الاولى في ( روسيا ) ..", "ففي ايلول عام ١٩٦١ نشرت جريدة ( البرافدا ) الناطقة بلسان اللجنة المركزية للحزب الشيوعي في الاتحاد السوفياتي مشروع برنامج جديد للحزب ، يؤكد للمرة الثالثة خروج الحزب عن مبادئه الاساسية .. فقد تضمن المشروع فكرة الغاء النهج الثوري الذي تعتمده الشيوعية في هدم الكيان الرأسمالي والذي نصت عليه الفقرة الواردة في الصفحة ٢٥ من كتاب ( المادية الدياليكتيكية ) بما يلي ( وبالتالي فالانتقال من الرأسمالية الى الاشتراكية وتحرير الطبقة العاملة من النير الرأسمالي .. يمكن تحقيقها لا بتغييرات بطيئة ولا باصلاحات . بل بتغيير كيفي للنظام الرأسمالي أي بالثورة ) وهذا ما جعل - بيكين وموسكو - في السنوات الاخيرة مسرحا لانشقاق كبير وخطير على مستقبل الاتجاه الماركسي نفسه ..", "وفضلا عن جنوح المنهج الجديد الذي - نشرته الجريدة المذكورة - عن فلك النظام الاساسي للحزب الشيوعي ،"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0032.png"}, {"n": 33, "paras": ["فقد اكد المنهج من خلال تعهده بتحقيق المجتمع الشيوعي خلال العشرين سنة المقبلة ، فشل النظام الشيوعي خلال الاربعين سنة الماضية في خلق الاساس الايديولوجي والمادي للمجتمع الشيوعي . وهذا يعني بدون شك ان الشيوعية كفكرة فقدت القدرة على ( تسميه بالحتمية التاريخية في الانتقال من الرأسمالية الى الاشتراكية) . ويعود منشأ هذا العجز ، الى ان النظرية الشيوعية لا ترتكز على اصول وقواعد عامة شاملة مرنة .. مما عرضها الى كثير من التعديل والتبديل في نظرياتها المنهجية والفكرية ..", "فمبدأ محو الملكية الفردية عدل عنه إلى حل وسط .. وهو الاحتفاظ للدولة بالصناعات الثقيلة والتجارة الخارجية والمصارف والمشاريع العامه .. كذلك عدل عن مبدأ توزيع السلع الاستهلاكية .. فبدل ان كانت القاعدة ( من كل حسب قدرته ولكل حسب حاجته ) اصبحت كما نص عليها الدستور السوفياتي المعدل عام ١٩٣٦ ( من كل حسب قدرته ولكل حسب ما يؤديه من عمل ، ومن لا عمل له له ليس الحق في ان يأكل ) ثم جاء الشروع الجديد الصادر عام ١٩٦١ يشير الى ان الاتحاد السوفياتي سيطبق خلال العشر سنوات الواقعة ما بين ( ١٩٧١ - ١٩٨٠ ) مبدأ التوزيع حسب الحاجة .. وبذلك يتراجع الشيوعيون مرة اخرى عن تعديل عام ١٩٣٦"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0033.png"}, {"n": 34, "paras": ["ومن شواهد الفشل التطبيقي لمبدأ المساواة في المجتمع الشيوعي .. يقول ( كرين برنتون ) في كتابه ( الثورة الشيوعية عناصرها - تحليلها - نتائجها - صفحة ٣٣٥ ) : يعيش الروس الان - كما يعرف حتى المناصرون للشيوعية في مجتمع يتفاوت فيه توزيع السلع الاستهلاكية ودخل الفرد تفاوتا كبيرا .. فالسياسي الروسي ذو المكانة ، او مدير المصنع او الكاتب او راقصة الباليه ، يتمتع هؤلاء بثروة مادية تجعل من المجتمع الروسي مجتمعا يفتقر في اساسه الى المساواة الاقتصادية بقدر ما يفتقر اليها أي مجتمع رأسمالي .. )", "وثمة شواهد كثيرة على اخفاق ( الشيوعية ) في مجالات التطبيق يضيق المجال لتعدادها ...", "ب - فشل الغرب في مجال التطبيق", "خدع كثير من شبابنا بمظاهر المدنية الغربية .. وظنوا أن نظافة القوم في مظاهرهم دليل على نظافة ارواحهم وضمائرهم .. وان سبقهم في ميادين الكشوف والاختراع يكفي لجعلهم مُثُلا عليا في كل شيء ..", "ولكن ما كانت المبادىء لتوزن في ميزان الحق بوفرة انتاجها الآلي. بل بما حققته في المجتمع من قيم اخلاقية وانسانية.", "والحضارة الغربية بهذا المقياس مفلسة غاية الافلاس ...", "- ٣٣ - الاسلام - ٣"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0034.png"}, {"n": 35, "paras": ["واننا لا نجد من معاني الشعارات التي ينادي بها الغربيون الا مظاهر التضليل والخداع .. يقول الاستاذ ( جودا ) استاذ الفلسفة الانجليزية في كتابه ( سخافات المدنية الحديثة ) : ان المدنية الحديثة ليس فيها توازن بين القوة والاخلاق .. فالاخلاق متأخرة جدا عن العلم . ومنذ النهضة ظل العلم في ارتقاء والاخلاق في انحطاط ، حتى بعدت المسافة بينهما .. وبينما يتراءى الجيل الجديد للناظر فتعجبه خوارقه الصناعية وتسخير المادة والقوى الطبيعية لمصالحه وأغراضه ، اذ هو يمتاز في اخلاقه .. في شرهه وطمعه .. في طيشه ونزقه .. وفي قسوته وظلمه عن غيره .. وبينما هو قد ملك جميع وسائل الحياة .. ( الى ان يقول ) اذا هو لا يدري كيف يعيش !!", "فشل الغربيين في تطبيق مبدأ المساواة :", "ففي نطاق المساواة فشل الغرب فشلا ذريعا في تطبيق مبدأ المساواة العنصرية والطبقية بين الناس .. فالتمييز العنصري لا يزال مشكلة المشاكل في اميركا .. واحتقار البيض للملونين في البلد الذي يدعي الحرية كرسته القوانين الرسمية نفسها .. فالرجل الاسود محروم من التعليم في مدارس البيض .. وهو محروم من تأدية العبادة في معابد البيض .. بل هو ممنوع في بعض الولايات من السير في شوارع البيض ؟؟ ومما روته الصحافة"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0035.png"}, {"n": 36, "paras": ["الغربية عن قصص التمييز العنصري مؤخرا القصة التالية ( لقد افرج عن القس الزنجي الاميركي ( وليمس كنج ) من العاشرة صباح الاحد حتى التاسعة من صباح الاثنين ، لحضور الصلاة العامة . ثم اعيد بعدها الى السجن ليقضي مدة العقوبة المحكوم بها ، لأنه اكل في مطاعم البيض ؟؟ )", "وفي اتحاد جنوب افريقيا اجرت ( بريطانيا ) استفتاء مزيفا لتقرير بقاء الاتحاد عضوا في الكومنولث البريطاني او اعلان الجمهورية فيه . وقد اعطي هذا الحق لجميع الاوروبيين المقيمين في الاتحاد وعددهم مليون ونصف مليون شخص .. بينما حرم منه سكان البلاد الوطنيون الاصليون وعددهم تسعة ملايين ونصف مليون نسمة ؟", "كذب الغربيين في دعوى الحرية والسلام :", "وأجدني في غنى عن تقديم شواهد على فشل الغرب وكذبه في دعوى السلام والحرية .. فالعالم العربي والاسلامي عانى وما يزال يعاني الكثير من ويلات الاستعمار وخداعه ووحشيته .. وها هي اميركا اليوم ترتكب باسم الحرية والسلام في فيتنام وغيرها ابشع المجازر .. لتقدم بين يدي العالم من جديد دليل افلاسها الانساني والاخلاقي والعقائدي .. كذلك القول فيما قامت به بريطانيا من تقتيل وتدمير في جنوب الجزيرة العربية باسم الحرية والسلام .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0036.png"}, {"n": 37, "paras": ["ويعلق الاستاذ ( جودا ) على ذلك في كتابه (سخافات المدنية الحديثة ) فيقول : ( انظر الى الطيارة التي تحلق في السماء ... يخيل اليك ان صانعيها في علمهم ولباقتهم فوق البشر .. ولكن انظر الى المقاصد السيئة التي استخدمت لها الطيارة وغيرها من المخترعات .. انما هي قذف القنابل ، وتمزيق جثث الانسان ، وخنق الاحياء بالغازات السامة ، واحراق الاجساد .. وهذا من مقاصد الحمقى او مقاصد الشياطين.. )", "الاسلام ضرورة ..", "اذا كانت هذه هي ابسط مظاهر الفشل التي تواجهها الاتجاهات الفكرية والمعسكرات السياسية في العالم اجمع ..", "واذا كان المنهج الاسلامي - التجربة الوحيدة - في حياة الانسانية التي برهنت عن اصالتها وعمقها .. والتي حققت النجاح ، وبلغت الكمال .. فقد بات على الامة ان تلتمس بواعث نهضتها وعوامل قوتها وطريق وحدتها وحريتها تحت راية الاسلام المجيدة وفي ظل قيادته الرشيدة .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0037.png"}, {"n": 38, "paras": ["الحركة الإسلامية بَيْنَ الأَمْسِ وَاليَوْمِ"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0038.png"}, {"n": 39, "paras": ["فصل في أحكام المرتد", "المرتد هو الذي يقطع الإسلام بنية أو قول كفر أو فعل، سواء كان استهزاء أو عناداً أو اعتقاداً.", "ومن أتى بناقض من نواقض الإسلام، وجب عليه التوبة فوراً، والرجوع إلى الإسلام بالشهادتين، والإقلاع عما وقع فيه من كفر.", "قال الله تعالى: ﴿وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِ فَيَمُتْ وَهُوَ كَافِرٌ فَأُولَٰئِكَ حَبِطَتْ أَعْمَالُهُمْ فِي الدُّنْيَا وَالْآخِرَةِ ۖ وَأُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ﴾.", "فالردة تحبط العمل، وتوجب الخلود في النار إن لم يتب العبد منها قبل الموت.", "ومن أحكام المرتد:", "١- بطلان عقده للنكاح، فلا يحل له أن يمسك زوجته المسلمة أو الكتابية.", "٢- لا يرث ولا يورث، فلا يرث من أقاربه المسلمين، ولا يرثه أقاربه المسلمون.", "٣- لا يغسل ولا يصلى عليه ولا يدفن في مقابر المسلمين إذا مات على ردته.", "والواجب على ولي الأمر أو من ينوب عنه دعوة المرتد إلى التوبة، وإزالة الشبهة التي قد تكون عرضت له، فإن أصر على كفره، أقيم عليه حد الردة."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0039.png"}, {"n": 40, "paras": ["اجدني في غير حاجة الى كبير جهد للتأكيد على ان مبادىء الاسلام واهدافه الكبرى اضخم من ان يضطلع بحملها والعمل لها افراد متفرقون لا يلتقون على وحدة في التصور ووحدة في التخطيط ..", "فالاسلام دعوة - هدم وبناء - هدم الجاهلية بكل صورها واشكالها .. سواء كانت جاهلية افكار ، ام جاهلية اخلاق ؛ ام جاهلية نظم وتشاريع .. ومن ثم بناء المجتمع على ( قواعد الاسلام ) في شكله ومحتواه .. في مظهره وجوهره .. في نظام حكمه .. واسلوب عيشه .. في تطلعه ( العقيدي ) للكون والانسان والحياة.. وفي تقويمه(الفطري)للاشياء كل الاشياء .. والاسلام متفرد بخصائصه فريد في مواصفاته .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0040.png"}, {"n": 41, "paras": ["فهو دعوةُ استعلاء واعتزاز يرفض ( المساومة ) ولا يقبل بالترقيع وانصاف الحلول .. وهو دعوةُ حق لا يستسيغ الوصول اليه بغيره .. فهو يرفض ( المكيافلية ) (١) اساساً ..", "ان نظرة الاسلام تفرض قيام البناء كل البناء من اصغر لبناته الى اضخم اعمدته واساساته وفق هندسة الاسلام واصوله وخصائصه ..", "وهذا يتطلب من ( التكاليف ) ما يعجز عنه الافراد ، ولا يقوى على النهوض به - مع الجهد الشاق - الا تنظيمٌ حركي تتوافر لديه الكفاياتُ الفكريةُ والفنية والمادية ، ويتوفر في اتباعه الوعيُ والجرأةُ والاخلاص ..", "حاجة التشريع الى دولة :", "والاسلام في محتواه ( القانوني ) ومضمونه ( التشريعي ) لا يمكن ان يتخطى النطاق النظري الى الواقع العملي دون ان تكون له ( دولة ) تحتكم اليه وتصدر عنه في كافة شؤونها .. وغيابُ الوجودِ ( الحكومي ) للاسلام يؤكد - كذلك -", "(١) نسبة الى مكيافيلي صاحب كتاب الامير الذي فصل فيه بين السياسة والاخلاق وسوغ فيه مباديء الحكم المنافية للاداب الانسانية ومن افظعها مبدأ ( الغاية تبرر الوسيلة )"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0041.png"}, {"n": 42, "paras": ["ضرورة قيام تنظيم حركي يكون من مبررات وجوده ( تحضير ) كافة المستلزمات والمقومات التي يتطلبها قيام الحكم الاسلامي.", "ولقد تسبب غياب الوجود ( الحكومي ) للاسلام فترة من الزمن في نشوء كثير من الشبهات ما كانت لتنشأ لو كان له دولة تحمله وتحميه .. تنافح عنه خصومه ، وتجسد مبادئه .. وتكون صورة حية لقيمه ومثله .. ومن هنا تبرز - ضرورة أخرى - من ضرورات قيام التنظيم الحركي بالتمهيد الكافي لاستئناف الحياة الاسلامية ..", "بين العمل الفردي والعمل الحركي :", "ثم ان المراقب لما يجري في نطاق العمل الاسلامي يلاحظ ان مآل الجهود الفردية الغير مرتبطة بتنظيم حركي - كالتي يبذلها الوعاظ والمرشدون والخطباء والموجهون - مآلها الى الضياع والهدر برغم كثرتها .. ذلك ان التنظيم الحركي من شأنه ان يستوعب الطاقات الفردية ويوجهها ويختزن القوى المتفرقة وينميها ، لتصبح على الزمن تياراً قوياً هادراً له أثره ومفعوله في عملية ( الهدم والبناء ) ..", "اما معاول الاصلاح الفردي فقد تتحطم إثر بعضها البعض لعجزها عن مواجهة تحديات العصر وبذلك تضيع على الاسلام امكانيات وجهود كثيرة ، كما تضيع الصيحات"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0042.png"}, {"n": 43, "paras": ["الخافتة في الوسط اللجب دون ان يُحس بها احد ، ويكون مثلها كصيحة في واد ونفخة في رماد ..", "الهدم والبناء عملية شاقة :", "وهنالك نقطة اخرى ينبغي ادراكها ولا يجوز اغفالها وهي ان طريق العمل الاسلامي مفروشة بالمحن محفوفة بالاخطار .. فالعقبات التي تعترض الطريق اكثر من ان تحصى .. والقوى التي تتربص بالاسلام واهله لا تعد .. والمشكلات التي خلفتها الحضارات والفلسفات المادية الغازية تتطلب انجع الحلول واسرعها ، واضخم الامكانات واحسنها .. زد على ذلك جهل المسلمين بهذا الدين وتحللهم من مبادئه واخلاقه .. مما يحتم قيام تنظيم حركي قوي يكون على قدر المسؤولية وفي مستواها ..", "نشأة الحركة الاسلامية الاولى", "ولقد ادرك الرسول صلى الله عليه وسلم من اول يوم ان تكاليف العمل الاسلامي ضخمة وشاقة .. وان عليه ان يُعد لحملها ما وسعه الاعداد ..", "وإن نظرة سريعة الى النهج الذي اعتمده الرسول صلى الله عليه وسلم في التحضير لبناء المجتمع الاسلامي وقيام"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0043.png"}, {"n": 44, "paras": ["الحكم الاسلامي تكفي للتأكيد على ان اسلوب العمل الجماعي والتنظيم الحركي هو النهج الاسلم والاسلوب الاقوم .. كان الرسول صلى الله عليه وسلم طيلة ( الثلاثة عشر عاماً ) التي قضاها في مكة عاكفاً على اعداد ( الطليعة الاولى للحركة الاسلامية ) . كان يُعدها لتكون على قدر العبء الذي ينتظرها .. فلنستعرض - بايجاز - هذه الفترة الزمنية الهامة من حياة الدعوة ونواكب نشأة الحركة الاسلامية الاولى فيها ..", "قواعد التنظيم الحركي", "١ - الوعي العقائدي", "كان محمد صلى الله عليه وسلم شديد الحرص على ان يأتي التنظيم الحركي نتيجة الوعي الاسلامي وثمرة من ثماره .. فلم تكن ( العاطفة ) قوة الدفع في كيان الدعوة ، بل كانت العقيدة اساس البناء كله .. كان الايمان الواعي وقود النفوس ومحركها الاصيل في جهادها الشاق الطويل .. ولهذا لم يتخذ التنظيم الحركي في عهد النبوة شكلا ( حزبياً ) كالذي نراه في التنظيمات السياسية الحديثة .. لم تكن الجماعة الاسلامية ( قطيعاً ) يسير وراء القيادة على غير هدى .. وانما"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0044.png"}, {"n": 45, "paras": ["كانت ملامح ذلك التنظيم تؤكد العمق العقائدي فيه ..", "لم تكن التبعية في ( الحركة الاسلامية ) لأشخاص .. كما لم يكن الاقبال عليها والانتساب اليها يستهدف مصالح العاملين فيها .. بل كانت التبعية للمبادىء ، وكان طمع الاتباع في رضاء الله عز وجل . قال : شداد بن الهاد ( جاء رجل من الاعراب الى النبي صلى الله عليه وسلم ، فآمن به واتبعه . فقال : اهاجر معك . فأوصى به بعض الصحابة .. فلما كانت ( غزوة خيبر ) غَنِم رسول الله صلى الله عليه وسلم شيئاً ، فقسمه للاعرابي . فقال الاعرابي للرسول : ما على هذا اتبعتك . ولكن اتبعتك على ان أرمى ها هنا - واشار الى حلقه - بسهم فأموت فادخل الجنة ، فقال الرسول صلى الله عليه وسلم : ان تصدّق الله ليصدقنك الله . ثم نهضوا الى القتال . فأتي به وهو مقتول .. فقال الرسول اهو هو ؟ فقالوا : نعم .. قال : صدق الله فصدقه .. )", "هذا الوعي العقائدي هو الذي حفظ كيان الحركة الاسلامية من الانفراط بعد موت الرسول صلى الله عليه وسلم . ولقد تجسد في اجلى صورة واوقع بيان حين وقف ابو بكر الصديق رضي الله عنه يعلن على الملأ ( من كان يعبد محمداً فان محمداً قد مات ومن كان يعبد الله فان الله حي لا يموت ) ثم يقرأ على الناس قوله تعالى ( وما محمد الا رسول قد خلت"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0045.png"}, {"n": 46, "paras": ["من قبله الرسل ، أفئن مات او قتل انقلبتم على اعقابكم . الآية ) . لقد تجلى الوعي العقائدي في حياة المسلمين الخاصة والعامة . كان البصر الثاقب .. والعقل الراجح .. والبصيرة النافذة .. بل كان الضياء والنور وصوت الضمير في كيان الفرد والجماعة", "٢ - التفاعل الحركي", "ولم يكن هدف الرسول صلى الله عليه وسلم من تعميق الوعي العقائدي في كيان الجماعة انشاء ( مدرسة نظرية ) وانما كانت الغاية الاساسية تحقيق التفاعل بين الفكرة والحركة .. فالاسلام يريد لمبادئه ان يكون لها الدور القيادي في حياة الناس.. فالاسلام ليس دين رهبانية ينعزل بأصحابه في الصوامع . بل هو دين حركة وتفاعل وجهاد .. وأتباعه ينبغي ان يكونوا رهباناً في الليل فرساناً في النهار .. ولهذا كانت المحنة في حياة الحركة الاسلامية اتوناً يصهر المعادن وينفي الخبث ( فاما الزبد فيذهب جفاء واما ما ينفع الناس فيمكث في الارض ) . فالذين امنوا حق الايمان ، وتفاعلوا مع الاسلام حق التفاعل اولئك مصابيح الهدى تنجلي عندهم كل فتنة عمياء .. ولقد شهد التاريخ الاسلامي في عصوره المختلفة نماذج رائعة"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0046.png"}, {"n": 47, "paras": ["من رجال صدقوا ما عاهدوا الله عليه فمنهم من قضى نحبه ومنهم من ينتظر وما بدلوا تبديلا .. على هذه الاسس نشأت الحركة الاسلامية الاولى .. مؤمنة بدعوتها .. متفاعلة مع المبادىء التي تحملها .. مدركة اخطار الطريق التي تسلكها .. مستعدة للبذل والعطاء برضى وسخاء.. ولما تمض فترة من الزمن حتى كان للحركة الاسلامية دولة تحكم بما انزل الله .. ونمت هذه الدولة مع الزمن واتسعت مع الايام حتى غدت ملء عين العالم وسمعه وبصره..", "المنجزات التي حققتها الحركة الاسلامية في صدر الاسلام", "لقد قدمت الحركة الاسلامية للبشرية في صدر الاسلام خدمات تعادل في حساب الزمن عشرات القرون.. وحققت من المنجزات والمعجزات ما استطاعت ان تغير به وجه التاريخ . من هذه المنجزات :", "١ - انها حررت النفس البشرية من عبودية غير الله.. فقضت بذلك على الوثنية والالحاد والشرك واستأصلت شأفتها من ارض العرب ..", "٢ - اسست اول وحدة ( عقيدية وسياسية ) في حياة العرب .. فقضت بذلك على النزعات القبلية والنعرات الاقليمية والمذهبية والعنصرية ."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0047.png"}, {"n": 48, "paras": ["٣ - انشأت اول حكومة ( شورية ) استمدت تشريعها من القرآن والسنة . فقضت بذلك على حاكمية البشر للبشر واعلنت ان الحاكمية لله ..", "٤ - حررت اطراف الجزيرة وبلاد الشام والعراق ومصر وشمالي افريقيا من براثن الاستعمار الروماني والفارسي ومن انحرافات الصليبية والمجوسية . فهدمت السدود وفتحت الحدود وحققت الامن والسلام واصبح الراكب يسير في الارض لا يخاف الا الله والذئب على غنمه ..", "٥ - قدمت للانسانية تراثاً ضخماً من العلم والحضارة لا تزال تعيش على اثاره حتى اليوم .. كما ملأت اسفار التاريخ بالعظماء من علماء وادباء وشعراء وحكماء ومجاهدين وشهداء . واذا كانت الايام دولا يداولها الله بين الناس بما كسبت ايدي الناس ولحكمة يراها هو ولا يراها سواه .. فان ذلك النور والخير الذي ملأ الدنيا اخذ بالأفول والانكماش ولم تزل قوة المسلمين تضعف يوماً بعد يوم الى ان مزق التتار حكومة ( خوارزم شاه ) في القرن السابع ، وسقطت بغداد عاصمة الدولة الاسلامية الاخيرة .. وهكذا فقد العالم الاسلامي مكانته القيادية واصبح عالةً على الشرق والغرب يستجدي منهما افكاره ومبادئه ونظمه .. وغرق المسلمون في التقليد وان ساقوا في تيار الحضارة الغربية لا يلوون على شيء .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0048.png"}, {"n": 49, "paras": ["ولكن على الرغم من هذا الانحدار الذي آل اليه العالم الاسلامي فقد بقي ( الاسلام ) محتفظاً بفعالياته وخصائصه .. وبقيت اصوات من الحق تتردد قويةً وضعيفةً على مر العصور والدهور لتؤكد سنة الله في كونه واعجازه في دينه ( لا تزال من امتي طائفة قائمة على الحق لا يضرهم من خالفهم حتى يأتي امر الله .. )", "طلائع الحركة الاسلامية في العصر الحديث", "في نهاية القرن التاسع عشر بدت طلائع الزحف الاسلامي من جديد .. وارتفع الصوت الاول للحركة الاسلامية الحديثة.. وصدق رسول الله صلى الله عليه وسلم حيث يقول ( ان الله يبعث لهذه الامة على رأس كل مائة سنة من يجدد امر دينها ) وقد اتفق علماء التاريخ على ان مجدد المائة الاولى ( عمر بن عبد العزيز ) والثانية ( الامام الشافعي ) والثالثة ( الاشعري ) والرابعة ( الباقلاني ) والخامسة ( حجة الاسلام الغزالي ) ... وهكذا صدق الله وعده وقيض لهذه الامة في القرن الرابع عشر الهجري رجالا جددوا هذا الدين وبعثوا تراثه وجمعوا القلوب حوله وجاهدوا فيه حق الجهاد .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0049.png"}, {"n": 50, "paras": ["الوهابية والسنوسية", "في القرن الثامن عشر الميلادي ظهرت الحركة الوهابية بقيادة ( محمد بن عبد الوهاب ) ( ١ ) تحارب البدع والحرافات وتدعو الى جوهر الدين .. الا ان تطرفا شديدا ومغالاة جافة شوهاء تسربت الى هذه الدعوة وحالت دون امتدادها وانتشارها .. ولقد قاومها الطغاة مقاومة شديدة حتى ان والي مصر انذاك ( محمد علي باشا ) عبأ لحربها الجيوش ، وملأ أرض الحجاز بدماء المسلمين .", "وتقارب الوهابية في عصرها حركة اخرى ظهرت في ليبيا ، هي ( الحركة السنوسية ) التي تنتسب الى السيد محمد بن علي السنوسي (٢) .. وقد بذل السنوسي جهودا جبارة في الدعوة الى الاسلام .. وكان لحركته اثار حسنة في الساحل الشمالي من افريقيا وخاصة في المغرب والسودان والصحراء الكبرى ..", "وفي اواخر القرن الثامن عشر الميلادي بذر جمال الدين", "(١) ولد محمد بن عبد الوهاب في ( العيينة ) من نجد عام ١٠١٦ ه الموافق ١٧٠٤ م ويقال ان جده سليمان رأى في المنام نارا خرجت من سرته فأضاءت البوادي كلها . فعبر بعضهم هذه الرؤيا بأنه يخرج من صلبه رجل يهدى الناس ويؤسس ملكا كبيرا ، فكان ذلك الرجل هو حفيده محمد بن عبد الوهاب .", "(٢) ولد محمد بن علي السنوسي عام ١٧٨٧ في بلدة ( مستغانم ) من بلاد الجزائر وتوفي عام ١٨٥٩", "- ٤٩ - الاسلام - ٤"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0050.png"}, {"n": 51, "paras": ["الافغاني (١) البذرة الثانية في كيان الحركة الاسلامية الحديثة .. وتتلخص دعوة الافغاني انذاك في نقاط ثلاث :", "١ - اصلاح عام شامل للحياة الدينية والاجتماعية والاقتصادية والسياسية والعودة الى الاسلام في صدره الاول .", "٢ - اصلاح سياسي يقوم على الشورى الاسلامية ممثلة في الحكم النيابي .", "٣ - الدعوة الى انضمام الدول الاسلامية في جامعة اسلامية واحدة ..", "ولم تسلم حركة الافغاني من المقاومة ، فقد حاربها ( الخديوي توفيق ) حرباً شعواء انتهت بنفي الافغاني من مصر عام ١٨٧١ بعد ان خلق فيها رأيا عاما ثائرا ومدرسة تؤمن بالحق وتنشده . وكان من تلاميذ هذه المدرسة الامام ( محمد", "(١) ولد جمال الدين الافغاني في ( اسد اباد ) من بلاد فارس عام ١٨٣٩ . ثم انتقل الى الافغان ، وفيها تعلم الفقه على مذهب ابي حنيفة ، ثم سافر الى مصر ومنها الى منفاه .. وفي اوروبا اصدر صحيفة ( العروة الوثقى ) وصحيفة ( ضياء الخافقين ) وتوفي عام ١٨٩٧ . وفي حياة الافغاني علامة تعجب كبرى - ارى من الحق ذكرها - وهي انتماؤه للحركة الماسونية وانشاؤه محفلا ماسونيا في مصر ، وان كان هذا المحفل كما قيل بعيدا عن سيطرة المحافل الغربية ؟؟"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0051.png"}, {"n": 52, "paras": ["عبده (١) ) الذي ألقي القبض عليه بعدئذ بتهمة قلب نظام الحكم ، ثم نفي من البلاد ولحق باستاذه الافغاني في باريس ..", "وكان من هذه المدرسة الامام السيد رشيد رضا (٢) الذي حمل لواء الجهاد في سبيل الاسلام اربعين عاما متصلة الحلقات مما حدا بشكيب ارسلان ان يقول فيه ( انه منذ اوحي الى محمد صلى الله عليه وسلم اقرأ باسم ربك خلق الى ساعتنا هذه ، ومنذ نشأة الامة المحمدية ، وقد نبغ فيها من الامراء والعلماء والقواد والحكماء ورجال السيف والقلم وعدد كبير من العبقريين والمشاهير والاقطاب . فسواء قل هذا العدد او كثر", "(١) ولد الامام محمد عبده عام ١٨٤٨ في قرية ( شتراء ) المصرية . وقد اثر الافغاني فيه تاثيرا كبيرا ووجه حياته توجيها جديدا ، فكان ان ساهم معه في دعوته ، وكان رفيقه في منفاه . ومن اقواله فيه ( ان ابي وهبني حياة يشاركني فيها ( علي ومحروس ) وهما اخوان له كانا مزارعين . والسيد جمال الدين وهبني حياة اشارك فيها ( محمدا وابراهيم وموسى وعيسى والولياء والقديسين ) وكانت وفاته بالاسكندرية عام ١٩٠٥", "(٢) ولد السيد رشيد رضا في قرية ( القلمون ) من لبنان عام ١٨٦٥ وتلقى علومه في مدينة طرابلس على يد الشيخ حسين الجسر . وقد افاد من دعوة الافغاني وتأثر بها ، ثم هاجر الى الشام ومنها الى مصر حيث تابع فيها خطواته الجبارة في ميدان الاصلاح . فأصدر مجلة ( المنار ) وعددا من المؤلفات منها : الوحي المحمدي - السنة والشيعة - حقيقة الربا - المقصورة الرشيدية - مناسك الحج - الخلافة والامامة العظمى - يسر الاسلام واصول التشريع العام - الوحدة الاسلامية - المنار والازهر - نداء للجنس اللطيف - تاريخ الامام عبده ."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0052.png"}, {"n": 53, "paras": ["فان السيد رشيد رضا من صيانه المعدودين في هؤلاء . ولا يمكن ان يكتب تاريخ الاسلام على الوجه الصحيح . ويوفر فيه لكل علم من اعلامه الحق الذي يستحقه ، بدون ان يكون لصحاب ( المنار ) فيه مقام كريم وبرهان ساطع . وليس التأخر في الزمان الذي يدعو الى التأخر في الرتبة .. )", "الحركة الاسلامية في الهند :", "وفي الهند قام الشيخ بن عبد الرحيم الدهلوي ( م ١١٧٦ ه ) المشهور بالشيخ ولي الله . وهو احد حكماء الاسلام ونوابغه وكبار المفكرين الاسلاميين من طراز الامام الغزالي وشيخ الاسلام ابن تيميه - قام بمهمة التجديد الاسلامي - وبعده قام نجله الاكبر سراج الهند الشيخ عبد العزيز الدهلوي ( ١٢٧٩ ه ) وكان له اثره الكبير في الدعوة الى الاسلام .", "وفي الربع الأول من القرن الثالث عشر الهجري قام السيد الامام احمد بن عرفان الشهير بمهام الدعوة الى الايمان والتقوى والجهاد في سبيل الله - فاستجاب له عدد كبير من الناس واستطاعوا ان يؤسسوا دولة اسلامية في مدينة ( بشاور ) وطبقوا فيها احكام الاسلام - ولكن القبائل الافغانية وجماعة ( السك ) تألبت عليهم وثارت ضدهم مما ادى الى قيام معركة عنيفة بين الطرفين قتل فيها الامام وكبار اصحابه وذلك ١٢٤٦ ه .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0053.png"}, {"n": 54, "paras": ["وفي سنة ١٨٥٧م ثار المسلمون ثورتهم المشهورة للتخلص من الانجليز - ولكن الثورة اخفقت ودخلت الهند في حكم بريطانيا المباشر - وطبقت الحكومة نظام التعليم المدني لتقطع الصلة بين الناشئة والاسلام - فلم ير العلماء بداً من فتح المدارس العربية والمعاهد الدينية لمكافحة تيار الحضارة الغربية الغازية - وبذلك تأسست ( مدرسة ديوبند ) سنة ١٢٨٣ ه ( ومدرسة مظاهر العلوم ) وفي عام ( ١٣١٦ ه ) انشأ القائمون على ندوة العلماء مدرسة ( دار العلوم ) التي اصبحت بعدئذ صرحاً من صروح الاسلام في الهند - وقد خرجت علماء ومؤلفين افذاذا نذكر منهم على سبيل المثال : الشيخ شبلي النعماني ، والشيخ سلمان الندوى، والسيد ابو الحسن الندوى وغيرهم ..", "الحركة الاسلامية في باكستان :", "وفي باكستان اصبح للحركة الاسلامية وزنها الاجتماعي والسياسي .. ففي عام ١٩٣٦ هجرية شمر الاستاذ ابو الاعلى المودودى عن ساعده للدفاع عن الدين واحياء اثره في النفوس.. فأنشأ مجلة ( ترجمان القرآن الشهرية ) تمهيدا لسبيل الدعوة وتوطئة لواجب العمل الاسلامي .. وفي عام ١٩٣٧ اعلن حربا شعواء على ( المؤتمر الوطني ) الهندي والقومية الهندية .. واستمر المودودى في جهاده الشاق الطويل يدعو الى الاسلام ويؤلف القلوب عليه ، ويتعهد الشباب بالتربية والتعليم ، حتى اذا كان"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0054.png"}, {"n": 55, "paras": ["عام ١٩٤٠ اجتمع نفر ممن سبقوا الى اجابة الدعوة في ( لاهور ) واتفقت كلمتهم على تأسيس ( الجماعة الاسلامية ) وانتخبوا ابا الاعلى المودودى اميرا لها . وجعلوا غايتها اقامة نظام الاسلام الكامل على وجه الارض وابتغاء وجه الله في الدار الآخرة .. وقد لاقت الجماعة الاسلامية في سبيل هذه الدعوة ما لاقت من المحن والمتاعب .. واصطدمت اصطدامات عنيفة بالفئات والاتجاهات التي أوجدها الاستعمار كالقاديانيين ، ومنكري السنة النبوية . والمتفرنجين . والمخدوعين بالحضارة الغربية .. وفي عام ١٩٦٣ صادرت الحكومة مجلة ( تَرْجُمان القرآن) والغت امتيازها بحجة ان المجلة حاولت اساءة العلاقة بين باكستان وايران ..", "وفي عام ١٩٦٤ أصدرت الحكومة اوامرها بحل الجماعة وصادرت اموالها وأغلقت دورها ومراكزها . ثم ألقي القبض على امير الجماعة وجميع اعضاء مجلس الشورى وهم ستون شخصا .. وزُج بهم في السجون والمعتقلات .. وبعدها قُدم المودودى للمحاكمة وصدر الحكم عليه بالاعدام لقاء تأليفه رسالة ( المسألة القاديانية ) وقد صدر هذا الحكم فعلا ثم خُفّض الى السجن المؤبد تحت ضغط العالم الاسلامي واستنكاره الشديد لموقف الحكومة من الجماعة الاسلامية . ولقد أسهم المودودى الى جانب قيامه بواجب الدعوة بامداد المكتبة الاسلامية بانتاجه وعبقريته فوضع عددا من الكتب والمؤلفات نذكر منها :"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0055.png"}, {"n": 56, "paras": ["مبادىء الاسلام - المصطلحات الاربعة في القرآن - الدين القيم - البيانات - المسألة القاديانية - الحجاب - الربا - معضلات الاقتصاد وحلها في الاسلام - نحو الدستور - منهج الانقلاب الاسلامي - الاسلام والجاهلية - . نظرية الاسلام الخلقية - الاسس الاخلاقية للحركة الاسلامية - واقع المسلمين وسبيل النهوض بهم - نظام الحياة في الاسلام . الجهاد في سبيل الله - شهادة الحق - وغيرها .", "الحركة الاسلامية في ايران :", "وفي ايران قامت الحركة الاسلامية وسط الحركات العديدة التي كانت تتجاذب هذا البلد الى اليمين والى اليسار .. فكان عليها واجب الوقوف بايران على الحياد وربطها بالعالم الاسلامي ومكافحة الاستعمار وعملائه .. وقد قيض الله للحركة حينئذ شابا متوقد الايمان والحماس يبلغ من العمر تسعة وعشرين عاما. درس في مدينة ( النجف ) بالعراق ثم عاد الى ايران ليقود حركة الجهاد ضد الخونة والمستعمرين .. اسس ( نواب صفوى ) حركة ( فدائيان اسلام ) التي تؤمن بان القوة والاعداد هي السبيل الوحيد لتطهير ارض الاسلام من الصهيونية والمستعمرين .. ولنعد بالذاكرة الى عام ١٩٤٨ ابان الحرب الفلسطينية حين لبس رجال جماعة ( فدائيان اسلام ) الاكفان واستعدوا للزحف"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0056.png"}, {"n": 57, "paras": ["الى فلسطين .. لكن توقيع الهدنة اعادهم . ولنعد كذلك الى معارك التحرير من النفوذ البريطاني عند تأميم مصافي ( عبادان ) فكان فدائيان اسلام هم الشعلة التي انارت السبيل ومهدت الطريق بسيل من الدماء ..", "واخيرا عندما نُقضت اتفاقات التأميم وانتكست الوثبة . كان لا بد لفدائيان اسلام من ان يعملوا .. فقال زعيمهم ( نواب ) بصراحة ( لا ) بالرغم من ان الكتل الوطنية كلها أسكتت او زُج بها في السجون .. فكان ان شرفه الله بالشهادة مع نفر من اخوانه .. وسقط نواب صفوي برصاص الخونة والعملاء صباح يوم الاربعاء الواقع في الخامس من جمادى الثانية ١٣٧٠ الموافق ١٨ من كانون الثاني ١٩٥٦", "واليوم وبعد ان اعترفت ايران باسرائيل عدوة الاسلام والمسلمين .. لا بد للعرب ان يتلمسوا في ايران نواب واخوان نواب .. لكن الدول العربية لم تدرك هذا حتى الان .. ولم تعلم بأن الحركة الاسلامية هي وحدها التي تدعم قضاياها خارج العالم العربي ..", "فهل لايران اليوم من ( نواب ) .. بل هل لزعماء العرب وقادتهم ان يتعظوا فيحفظوا لامثال نواب واخوانه جهادهم ومواقفهم ؟؟"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0057.png"}, {"n": 58, "paras": ["الحركة الاسلامية في اندونيسيا", "وفي اندونيسيا قام حزب ( ماشومي ) اي ( مجلس الشورى الاسلامي ) الذي يرأسه محمد ناصر بدعوة اندونيسيا الى الحكم الاسلامي والبعد بها عن سياسة الأحلاف والارتباطات الاجنبية.. ولقد قاومت الحركة الاسلامية السياسة الرامية الى اخضاع اندونيسيا للنفوذ الشيوعي ، وتمكين الفكر الماركسي من السيطرة والانتشار .. والى اليوم لا يزال حزب ماشومي حارسا لثغور الاسلام ومبادئه في اندونيسيا مرابطا في خط النار الاول.. ويقدر عدد المنتسبين الى الحركة الاسلامية في اندونيسيا بأكثر من عشر ملايين عضو ..", "الحركة الاسلامية في تركيا :", "وفي تركيا كانت الحركة الاسلامية على موعد مع المد الاسلامي الزاحف في كل مكان .. ولقد اوقد المجاهد الشيخ ( سعيد النورسي ) اول شعلة للكفاح الاسلامي في تركيا في اوائل القرن العشرين .. فألقى بنفسه الى معترك السياسة صغيرا حيث قُيدت يداه وهو لا يزال في الثامنة عشرة ونُفي الى ( تلبیس ) .. وبعد عودته من منفاه بدأ بتكوين اول لبنة للحركة الاسلامية في تركيا .. وفي عام ١٩٣٥ اتهم بانشاء جمعية سرية وقُدم للمحاكمة .. ومنذ ذلك الحين والحركة الاسلامية التي"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0058.png"}, {"n": 59, "paras": ["أسسها النورسي في نمو وانتشار حتى بلغ عدد المنتسبين اليها كما وصفته الصحف المعارضه لها ٦٠٠,٠٠٠ عضو . وعلى الرغم من المقاومة العنيفة التي تتعرض لها الحركة في تركيا فقد اصبحت لها دعائم قوية راسخة في المجتمع التركي وينطق بلسانها عدد من الصحف والمجلات ..", "الحركة الاسلامية في مصر :", "وفي مطلع القرن العشرين كانت مصر بل العالم الاسلامي من اقصاه الى اقصاه مع مجدد جليل من مجددي الدعوة الاسلامية وباعثي حركتها ، ذلك هو الامام الشهيد حسن البنا (١) نضر الله وجهه .", "ولقد تميزت حركته بوضوح ( الغاية ) وشمول ( الفكرة ) كما تميزت بالواقعية والتخطيط .. لقد جمعت بين العمق الفكري والتكوين الخلقي والعمل السياسي .. ولم يكن انطلاقها عفويا عاطفيا وانما كان انطلاقا مدروسا يبدأ بالتحليل والتشخيص وينتهي بالعمل والتنفيذ ..", "(١) ولد حسن البنا في ( المحمودية ) من الريف المصري عام ١٩٠٦ - وفي عام ١٩٢٧ تخرج من دار العلوم بالقاهرة - وفي عام ١٩٢٨ ولدت جماعة الاخوان المسلمين في مدينة الاسماعيلية - وفي عام ١٩٣٣ تأسس اول فرع للحركة في القاهرة - وفي عام ١٩٤٩ اغتيل الشهيد حسن البنا على يد ( القصر والانجليز )"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0059.png"}, {"n": 60, "paras": ["والحركة - كل حركة - حتى تكون ذات فاعلية واقعية في حياة الناس وواقعهم ينبغي ان تحدد مناهج عملها وترسم خط سيرها على ضوء تصورين اساسيين :", "تصور شامل للواقع المراد تغييره ، بكل ما فيه من مشكلات وتيارات وقوى واتجاهات . تصور يكفي لتحديد العوامل التي تسببت في تحلله وتداعيه .. اي تكفي لتشخيص امراضه وعلله ..", "وتصور واع للنهج والاسلوب اللذين سيعتمدان في عملية التغيير تحددها فلسفتها العقائدية ومبادئها الاصلاحية .", "فأما عن الاول .. فقد خرجت الحركة الاسلامية من دراستها للواقع ومشكلاته بتصور عميق حددت على ضوئه العامل الاساسي في اشقائه وافساده .. ذلكم هو الاعتداء على سلطان الله في الارض ، وعلى اخص خصائص الالوهية وهي ( الحاكمية ) .. فالواقع الانساني اسند الحاكمية الى البشر . وجعل بعضهم ارباب بعض. لا في الصورة البدائية الساذجة التي عرفتها الجاهلية الاولى .. ولكن في صورة ادعاء حق وضع التصورات والقيم والشرائع والقوانين والأنظمة ، بمعزل عن منهج الله للحياة وفيما لم يأذن به الله (١) .", "وأما عن الثاني .. فقد بينت الحركة الاسلامية ان مهمتها الاولى هي تغيير هذا الواقع من أساسه .. وأكدت انها لن", "(١) معالم في الطريق - للشهيد سيد قطب"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0060.png"}, {"n": 61, "paras": ["تصلح مع واقع هذا المجتمع الجاهلي او تدين له بالولاء .. وان وظيفتها الاولى هي احلال التصورات الاسلامية والتقاليد الاسلامية مكان هذه الجاهلية . وان هذا لن يتحقق بمجاراة الجاهلية والسير معها خطوات في الطريق ، وانما بالتمايز عنها والانقلاب عليها ..", "وعلى ضوء هذا التصور المبدائي لطبيعة العمل الاسلامي ومتطلباته رسمت الحركة الاسلامية خط سيرها وقسمته الى ثلاث مراحل :", "١ - مرحلة التعريف والتوعية : بنشر الفكرة وجلاء حقيقتها وبيان اهدافها ودعوة الناس اليها .", "٢ - مرحلة الاعداد والتكوين : باستخلاص العناصر الصالحة لحمل الاعباء ، وتكوينها واعدادها لتكون في مستوى المسؤ وليات التي تنتظرها .", "٣ - مرحلة التنفيذ : بتغيير الواقع القائم وتحقيق الواقع المنشود وفق خطة مرسومة ..", "دور الحركة الاسلامية الحديثة :", "لقد امتدت حركة الاخوان في كل مكان .. وأصبح لها في كل بلد دعوة ودعاء .. ولعبت في التاريخ المعاصر ادوارا بالغة الاهمية في مختلف الميادين .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0061.png"}, {"n": 62, "paras": ["على الصعيد الفكري", "فعلى الصعيد الفكري تولت الحركة الاسلامية احياء التراث الاسلامي وعرض الاسلام بأسلوب العصر عرضا علميا رصينا كشف عن ذخائر الفكر الاسلامي ..", "مفهوم الحركة للاسلام :", "حرصت الحركة من اول يوم على ان تزيل عن الاسلام ركام البدع والخرافات ، وتقدمه للناس بصورته الصافية المشرقة التي توافق طبيعته ومحتواه ..", "فهي تؤمن بأن احكام الاسلام وتعاليمه شاملة .. تنتظم شؤون الدنيا والآخرة .. فهي عقيدة وعبادة .. واخلاق وتشريع ووطن وجنسية .. ودين ودولة .. وروحانية وعمل .. ومصحف وسيف .. (١)", "وتعتبر الحركة الاسلامية ان القاعدة النظرية التي يقوم عليها الاسلام على مدار التاريخ البشري هي قاعدة ( لا اله الا الله ) اي أفراد الله سبحانه في الالوهية والربوبية والقوامة والسلطان والحاكمية .. افرادة بها اعتقادا في الضمير .. وعبادة في الشعائر .. وشريعة في واقع الحياة ( ٢ ) ..", "(١) رسالة المؤتمر الخامس - للشهيد حسن البنا", "(٢) معالم في الطريق - للشهيد سيد قطب"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0062.png"}, {"n": 63, "paras": ["النفس الانسانية مركز الثقل :", "أما عن النفس الانسانية فقد اختصتها الحركة الاسلامية بكبير الاهمية ، و اعتبرتها مركز الثقل في الحياة البشرية ، وان بصلاحها صلاح الحياة وبفسادها فساد المجتمع والناس .. فبينت موقف الاسلام منها وعنايته بها ومناهج التربية التي اعدها الاسلام لها .. أكدت الحركة ان طريقة الاسلام في التربية هي معالجة الكائن البشري كله ، معالجة شاملة لا تترك منه شيئا ولا تغفل عن شيء .. جسمه وعقله وروحه .. حياته المادية والمعنوية ، وكل نشاطه على الأرض ..", "وان الاسلام حرص على هذا التوازن وجعله هدفا اساسيا في منهاجه . وبذل فيه كل ما في الطاقة من جهد .. بدأ فيه مع الطفل من مولده .. وسار فيه مع الانسان في جميع مراحل حياته ونموه .. ولم يتركه لحظة دون معاونة او توجيه (١) .", "الحركة الاسلامية والحضارة الغربية :", "وكان موقف الحركة الاسلامية من الحضارة الغربية موقفا حاسما من اول يوم .. كشفت عيوبها .. وعددت مثالها .. وأماطت اللثام عن حقيقتها وجوهرها ..", "(١) منهج التربية الاسلامية - للاستاذ محمد قطب"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0063.png"}, {"n": 64, "paras": ["لقد بينت ان هذه الحضارة التي زهت بجمالها العلمي حينا من الدهر ، واخضعت العالم كله بنتائج هذا العلم ، تفلس اليوم وتندحر ، وتندك اصولها ، وتنهدم نظمها وقواعدها ..", "فالدول التي تمارس تجارب تطبيق ( النظريات الماركسية ) مثقلة بالضوائق والازمات في كل مجال . فمشكلات التأميم ومشكلات الغلاء ومشكلات حرب الطبقات وغيرها اصبحت عنوانا بارزا على فشل التطبيق الاشتراكي ..", "كذلك الدول التي تمارس تطبيق ( الانظمة الاقتصادية الحرة ) هي الاخرى غارقة في طوفان مشكلاتها الاجتماعية والاقتصادية كمشكلات الاحتكار والبطالة والربا والتسلط الفردي وغيرها ..", "وان العالم اصبح بسبب هذه النظم والاتجاهات المادية المنحرفة كسفينة في وسط اليم حار ربانها وهبت عليها العواصف من كل مكان . الانسانية كلها معذبة شقية قلقة قد اكتوت بنار المطامع والاستعمار فهي في اشد الحاجة الى عذب من سؤر الاسلام يغسل عنها اوضار الشقاء ويأخذ بها الى السعادة ..", "الحركة الاسلامية والابداع المادي :", "واذا كانت الحركة الاسلامية قد نددت بالحضارة الغربية فانها لم تتنكر للابداع المادي ، وانما انكرت اهليته لقيادة"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0064.png"}, {"n": 65, "paras": ["البشرية . وأكدت ان الاسلام لا يحتقر المادة ، ولكنه فقط لا يعتبرها هي القيمة العليا التي تهدر في سبيلها خصائص الانسان ومقوماته ، وتهدر من اجلها حرية الفرد وكرامته ، وتهدر فيها اخلاق المجتمع وحرماته .. وخلصت الحركة الاسلامية الى القول بانه لا بد من مؤهل آخر لقيادة البشرية .. مؤهل يسمح للبشرية ان تحتفظ بنتاج العبقرية والمادية ولكن تحت اشراف تصور آخر يلبي حاجة الفطرة (١) .", "الحركة الاسلامية والشيوعية : أما عن الشيوعية فقد اعتبرتها الحركة الاسلامية من أخطر الاتجاهات التي تهدد عقيدة الامة بالفناء والدمار . فالشيوعية تنكر بصراحة عقيدة الالوهية والرسالات والعالم الآخر - وتقول ( لا اله والحياة مادة ) والشيوعية تفسر التاريخ تفسيرا ماديا صرفا يجعل الحياة على وجه الأرض معركة امعاء وبطون . وتسقط من حسابها القيم والاخلاق والأفكار والمثل . والشيوعية تحارب الفطرة البشرية بمحوها للملكية الفردية . والشيوعية تثير الفتن والاحقاد ، وتذكي روح الانتقام بين ارباب العمل والعمال، وتضرم في المجتمع حرب الطبقات.", "(١) معالم في الطريق - للشهيد سيد قطب"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0065.png"}, {"n": 66, "paras": ["الحركة الاسلامية والقومية :", "واعتبرت الحركة الاسلامية ( القومية ) التي يراد بها الاعتزاز بالجنس الى درجة تؤدي الى انتقاص الاجناس الاخرى كما نادت بذلك ( المانيا وايطاليا ) معنى ذميما ليس من الانسانية في شيء .. وأكدت ان رسالة الاسلام فوق ما يسمى ( بالفرعونية والعربية والسورية وغيرها ) من الاتجاهات القومية .. وانها تؤ من بما قاله الرسول صلى الله عليه وسلم ( ان الله قد اذهب عنكم نخوة الجاهلية وتعاظمها بالاباء . الناس لآدم وآدم من تراب . لافضل لعربي على اعجمي الا بالتقوى . )", "والحركة الاسلامية لم تنكر مع هذا خواص الامم والشعوب فهي تؤمن بأن لكل شعب ميزاته وقسطه من الخلق والفضيلة . وان العرب لهم من ذلك النصيب الاوفى . ولكنها تنكر اعتبار هذه الميزات مصدرا عقيديا ومؤهلا فكريا يصرف العرب ويغنيهم عن رسالة الاسلام ..", "فالقومية في نظر الحركة الاسلامية كيان فارغ بحاجة الى املاء ، وعاطفة جياشة بحاجة الى دعائم فكرية وعقيدية .. وان منطق العصر يقضي بانفتاح الشعوب العربية على الشعوب الاسلامية التي تلتقي معها على وحدة في التصور ووحدة في الاعتقاد ووحدة في الآمال والآلام .. وان رسالتها الانسانية تفرض استعلاءها على الروابط الاقليمية والنزعات الشعوبية ..", "الاسلام - ٥ - ٦٥ -"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0066.png"}, {"n": 67, "paras": ["الحركة الاسلامية والوحدة :", "واعتبرت الحركة الاسلامية الوحدة مطلبا عزيزا من مطالبها وجزء لا يتجزأ من عقيدتها وهدفا كبيرا من اهدافها .. فالوحدة مبدأ من مبادىء الاسلام ، وصفة أساسية من صفات الامة الاسلامية ( وان هذه امتكم امة واحدة وأنا ربكم فاعبدون).. والحركة الاسلامية بهذا لا تعتبر الوحدة شعارا يطرح على مستوى حزبي محدود ، وفي اطار سياسي مغلوق ، ليتجر بها حزب ، او تقتات على حسابها فئة ..", "ولذلك فهي تدعو الى معالجتها والعمل لها بروح رحبة مستمدة من جوهر الإسلام الذاتي سلوكا اخلاقيا ورباطا عقيديا يربط القلب بالقلب والفكر بالفكر والهدف بالهدف من غير مساومة ولا خداع .", "وترى الحركة الاسلامية ان جميع المحاولات (الوحدوية) كانت تفتقر الى تخطيط دقيق وعميق يجسدها حقيقة ملموسة وكيانا قائما . وهذا ما جعل مفهومها سطحيا وعائما .. فتارة كانت ترمي الى تعزيز ( القوى العربية ) كلما لاح شبح الاستعمار والصهيونية .. وطورا كانت تهدف الى تدعيم ( الاقتصاد العربي ) كلما احدقت بالبلاد ضوائق معيشية ومالية .. الى غير ذلك من الاعتبارات والمصالح الزمنية الآنية .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0067.png"}, {"n": 68, "paras": ["والحركة الاسلامية لا تنكر ان الوحدة ضرورة ( سياسية وعسكرية واقتصادية) ولكنها تعتبرها قبل كل هذا تجسيدا لمبادىء الامة فضلا عن مصالحها .. ورمزا لاصرة الدين لا لرابطة الطين، ومظهرا عقيديا لا قوميا ولا عنصريا .", "فالحركة الاسلامية لا تعترف بالحدود الجغرافية المصطنعة ولا بالفوارق الجنسية ، وتعتبر المسلمين جميعا ( امة واحدة ) كما تعتبر الوطن الاسلامي وطنا واحدا مهما تباعدت اقطاره وتناءت دياره . وقد عبر عن هذا المعنى احد شعرائها بقوله : ولست أدري سوى الاسلام لي وطنا الشام فيه ووادي النيل سيان وحيثما ذكر اسم الله في بلد عددت ارجاءه من لب اوطاني", "تراث الحركة الفكري :", "ومن قبيل الانصاف القول بأن الحركة الاسلامية الحديثة ملأت ( المكتبة الاسلامية ) بشتى الموضوعات والمؤلفات والكتابات ، وقدمت للبشرية تراثا فكريا فريدا .", "وان شئتم بيانا فهاكم طائفة من الكتب والمؤلفات التي حفل بها تراث الحركة الاسلامية الضخم ."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0068.png"}, {"n": 69, "paras": ["في الدراسات الفكرية :", "- الانسان بين المادية والاسلام - للأستاذ محمد قطب", "- شبهات حول الاسلام - للاستاذ محمد قطب", "- هل نحن مسلمون - للاستاذ محمد قطب", "- التطور والثبات في حياة البشرية - للاستاذ محمد قطب", "- العدالة الاجتماعية في الاسلام - للشهيد سيد قطب", "- السلام العالمي والاسلام - للشهيد سيد قطب", "- خصائص التصور في الاسلام - للشهيد سيد قطب", "- هذا الدين - للشهيد سيد قطب", "- المستقبل لهذا الدين - للشهيد سيد قطب", "- دراسات اسلامية - للشهيد سيد قطب", "في الدراسات الفقهية والتشريعية :", "- التشريع الجنائي في الاسلام - للشهيد عبد القادر عودة", "- الحلال والحرام - للاستاذ يوسف القرضاوي", "- المرأة بين البيت والمجتمع - للاستاذ البهي الخولي", "- المال والحكم في الاسلام - للشهيد عبد القادر عودة", "- فقه السنة - للاستاذ سيد سابق", "- الاسلام وأوضاعنا القانونية - للشهيد عبد القادر عودة", "- الاسلام وأوضاعنا الاقتصادية - للشهيد عبد القادر عودة"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0069.png"}, {"n": 70, "paras": ["في الدراسات النفسية والتربوية :", "- منهج التربية الاسلامية - للاستاذ محمد قطب", "- في النفس والمجتمع - للاستاذ محمد قطب", "- منهج الفن الاسلامي - للاستاذ محمد قطب", "- دراسات في النفس الانسانية - للاستاذ محمد قطب", "- من مشاهد القيامة في القرآن - للشهيد سيد قطب", "- التصوير الفني في القرآن - للشهيد سيد قطب", "- معركة التقاليد - للاستاذ محمد قطب", "في الدراسات المقارنة والنقدية :", "- معركة الاسلام والرأسمالية - للشهيد سيد قطب", "- الاسلام ومشكلات الحضارة - للشهيد سيد قطب", "- جاهلية القرن العشرين - للاستاذ محمد قطب", "- الاسلام لا شيوعية ولا رأسمالية - للاستاذ البهي الخولي", "- الشيوعية والاسلام - للاستاذ عمر الهندي", "في الدراسات الحركية :", "- معالم في الطريق - للشهيد سيد قطب", "- تذكرة الدعاة - للاستاذ البهي الخولي", "- الهدم والبناء - للاستاذ عبد العزيز كامل"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0070.png"}, {"n": 71, "paras": ["- كيف ندعو الناس - للاستاذ عبد البديع صقر", "- مجموعة رسائل الامام الشهيد حسن البنا", "- مذكرات الدعوة والداعية - للشهيد حسن البنا", "- الاخوان في حرب فلسطين - للاستاذ كامل الشريف", "- الاخوان والمجتمع المصري - للاستاذ محمد شوقي زكي", "- المقاومة السرية - للاستاذ كامل الشريف", "- الاخوان المسلمون في ميزان الحق - للاستاذ انور الجندي", "- قائد الدعوة - للاستاذ انور الجندي", "- الوفد والاخوان في الميزان - للاستاذ كامل الشافعي", "- الامام جزء ١ - ٢ - للاستاذ احمد انس الحجاجي", "- صوت من الجنة - للاستاذ احمد انس الحجاجي", "- مع المرشد العام - للاستاذ لبيب البوهي", "- تاريخ الدعوة - للاستاذ احمد عبد الجليل", "- تاريخ الاحزاب السياسية - للاستاذ انور الجندي", "- حسن البنا كما عرفته - للاستاذ فتحي العسال", "على الصعيد السياسي", "وعلى الصعيد السياسي كان للحركة الاسلامية دورها الطليعي في مجاهدة الاستعمار وأعوانه ومقاومة الاحلاف الاجنبية وكل ما من شأنه اقحام العالم الاسلامي في مناطق نفوذ الاستعمار . وخاضت الحركة الاسلامية في سبيل ذلك"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0071.png"}, {"n": 72, "paras": ["اعنف المعارك واضراها وقدمت في ساحات الجهاد زهرة شبابها وخيرة رجالها ..", "واذا كانت الاتجاهات والزعامات الشعوبية التي تدعي الثوريه والتقدمية تستقطب لنفسها امجاد كل كفاح في التاريخ الحديث فان من حق الامة على الحركة الاسلامية ان تطالبها بكشف صفحاتها وتسجيل تاريخها حفاظا على الحقائق من سفه الحاقدين وصيانة للوقائع من عبث العابثين ..", "واذا كان دور الحركة الاسلامية في مجاهدة الاستعمار وأتباعه والمنفذين لمخططاته والسائرين على دربه والمستوردين لمبادئه بالغ الاهمية قديما وحديثا فلأن هؤلاء يرون في الحركة الاسلامية الخطر كل الخطر على مصالحهم وزعاماتهم وسياساتهم ومخططاتهم .. ويدركون تمام الادراك مدى القوة الكامنة في عقيدة الاسلام ومدى اثرها ومفعولها اذا استيقظت في المسلمين .", "ان الاستعمار والشيوعية والاتجاهات الشعوبية والحركات اليسارية تدرك هذا غاية الادراك وهي لذلك تعمل جاهدة للقضاء على كل تنظيم حركي للاسلام في العصر الحديث .", "١ - حرب الدس على الفكرة الاسلامية :", "ومن الوسائل التي اتبعها خصوم الاسلام لحرب الاسلام ذلك الدس الحاقد على الفكر الاسلامي وتشويه صفائه ونقائه .. ولقد جندوا لذلك اقلام الباطل في كل مكان للنيل من الاسلام"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0072.png"}, {"n": 73, "paras": ["والافتراء عليه عن طريق الكتب والمؤلفات ، ككتب المستشرقين وتلامذتهم امثال جرجي زيدان وسلامة موسى . وخالد محمد خالد . والاستاذ الحداد . وفيليب حتي . وعلي عبد الرزاق . وعبد الرحمن بدوي . وميشيل عفلق . وساطع الحصري . وجورج حبش وغيرهم .. ولقد وقفت الحركة الاسلامية بالمرصاد لهؤلاء الدساسين .. فكشفت ضلالاتهم وانحرافاتهم .. وفضحت نواياهم وغاياتهم.. وحذرت الجماهير المسلمة من كتبهم ومؤلفاتهم وأفكارهم ..", "٢ - حرب الشائعات على الحركة الاسلامية :", "ولم يكتف الاستعمار واتباعه وخصوم الاسلام وأعداؤه بالدس على الفكرة الاسلامية بل تعدوه الى الدس على الحركة الاسلامية .. فأثاروا حولها الشائعات والاراجيف واختلقوا لها التهم والاكاذيب ، ليقطعوا بذلك الطريق عليها ويزرعوا من حولها الشكوك بل ولينتزعوا ثقة الناس منها ويؤلبوهم عليها ( يريدون ليطفئوا نور الله بأفواههم والله متم نوره ولو كره الكافرون .. ) ولكن تاريخ الحركة الاسلامية انصع من ان تلوثه دعايات المغرضين وشائعات الحاقدين .. ان تاريخ الحركة الاسلامية في كل مكان صفحة ناصعة من الوطنية والاخلاص والفداء .. وحتى نكون موضوعيين لا بد من وضع النقاط على الحروف"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0073.png"}, {"n": 74, "paras": ["واستعراض التاريخ السياسي للحركة الاسلامية الحديثة ولو بإيجاز :", "لمحات من تاريخ الحركة السياسي في مصر", "كان عام ١٩٣٩ بداية النشاط السياسي للحركة الاسلامية في مصر .. وقد اقتصر في ذلك الحين على القيام بواجب النصح للحكومات المتعاقبة . وفي عهد ( علي ماهر ) أعلنت الحركة الاسلامية تأييدها لقرار تجنيب مصر ويلات الحرب ..", "وفي عام ١٩٤١ تعرضت الحركة الاسلامية للمحنة الاولى في عهد ( حسين سرى ) بضغط من السفارة البريطانية في القاهرة وقيادة جنود الإحتلال في قاعدة القنال . فعطلت في هذه الفترة مجلات الحركة الثلاث ( التعارف - والشعاع - والمنار ) واعتقل عدد من قادتها وفي طليعتهم الشهيد حسن البنا المرشد العام .", "وفي عام ١٩٤٤ تعرضت الحركة الاسلامية لمحنة جديدة في عهد حكومة ( احمد ماهر ) وقد اشتركت السلطات المصرية في ذلك الحين مع الانجليز في محاربة مرشحي الحركة الاسلامية في الانتخابات النيابية .", "وفي عام ١٩٤٦ أعلنت الحركة الاسلامية الجهاد ضد جنود الاحتلال البريطاني . وخاض رجالها أعنف المعارك ضد"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0074.png"}, {"n": 75, "paras": ["العدو الغاصب . واستمرت المعارك الدامية بينها وبين البريطانيين حتى عام ١٩٤٨ حيث نشبت الحرب ( الفلسطينية ) وأصبحت الحركة امام خصمين . القوات الانجليزية في الداخل والخطر الصهيوني في فلسطين . وصممت الحركة على خوض المعركة في فلسطين ، وأقيمت معسكرات التدريب ، وتدفق الشباب الجامعي على التطوع في كتائب الجهاد بحماس منقطع النظير ..", "وخاض المجاهدون المعركة ببسالة وايمان شهد بهما القريب والبعيد مما استرعى اعجاب الضباط المصريين انفسهم.. حتى ان انور السادات يقول في كتابه ( صفحات مجهولة من تاريخ الثورة المصرية ) صفحة ٢٥٦ ( وكانت اكثر الجماعات في ذلك الوقت حماساً للتطوع والقتال هي ( الحركة الاسلامية ) .. ولقد أبلى رجال الاسلام وشبابه في الجهاد البلاء الحسن .. وسقط منهم عدد كبير من الشهداء نذكر منهم : الشهيد عبد الرحمن عبد الخالق .. الشهيد الشيخ فرج ابراهيم .. الشهيد محمد عبد الرؤوف .. الشهيد عبد السميع قندللي . الشهيد عز العرب محمد سليمان .. الشهيد مصطفى الشربيني .. الشهيد محمد عبد الخالق يوسف .. الشهيد عبد الرحمن عبد الحي .. الشهيد محمود سلطان .. الخ ..", "وفي عام ١٩٤٨ وبينما كان مجاهدو الحركة الاسلامية في ارض المعركة يذودون عن الوطن بالمهج والارواح كانت الدوائر الاستعمارية تضع بالاشتراك مع القصر خطوط المؤامرة"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0075.png"}, {"n": 76, "paras": ["الخسيسة التي ذهب ضحيتها المرحوم الشهيد حسن البنا المرشد العام للحركة الاسلامية .", "وليت الأمر وقف عند هذا الحد .. بل لقد تعداه الى أبشع مؤامرة في التاريخ .. فقد صدرت أوامر القصر باعتقال المجاهدين في الجبهة وزجهم في المعتقلات الصحراوية .. وكانت مهزلة تدمي القلوب ان يُحمل المجاهدون من ميادين القتال الى الزنازن والسجون.. ولقد أشار الى ذلك انور السادات في نفس المصدر السابق صفحة ١٢ فقال : ( ورأى الشعب ابناءه الذين هبوا يذودون عن شرفه وحريته يعودون الى المدينة مكبلين بالاغلال ليقضوا أيامهم خلف اسوار المعتقل .. ) .", "جولة ثانية مع الانجليز :", "وفي عام ١٩٥١ خرج رجال الحركة الاسلامية من المعتقل. وبدأوا يُعدون لمعركة ثانية مع قوات الاحتلال البريطاني .. وأستأنفوا حرب العصابات بعمليات جريئة خاطفة .. وغمرت البلاد موجة من الحماس وخصوصا في اوساط الطلاب والجامعيين .. وقد أُنشئت معسكرات التدريب في الجامعات رغم المضايقات الحكومية الشديدة ..", "واستمرت العمليات العسكرية على طول قناة السويس والقاعدة البريطانية حتى استحالت القاعدة ساحة حرب تتلظى بالنار والدخان .. وقد سجل مجاهدو الحركة الاسلامية في تلك"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0076.png"}, {"n": 77, "paras": ["الفترة انصع صفحات البطولة حيث قابلوا بأسلحتهم الخفيفة مصفحات العدو ومدافعه .. فأضافوا بذلك عددا اخر من الشهداء الى سجل الخالدين نذكر منهم : الشهيد عمر شاهين .. الشهيد عادل غانم .. الشهيد نبيل منصور .. الشهيد احمد المنيسي .. الشهيد عباس الاعسر ..", "ومما يدل على امعان الحركة الاسلامية في مقاومة الانكليز ان الامام الشهيد حسن البنا وضع صيغة دعاء ليتلوه المسلمون في المساجد عقب الصلاة هذا نصه ( اللهم رب العالمين .. وأمان الخائفين .. ومذل المتكبرين .. وقاصم الجبارين .. تقبل دعاءنا وأجب نداءنا .. وأنلنا حقنا .. ورد علينا حريتنا واستقلالنا.. اللهم ان هؤلاء الغاصبين من البريطانيين قد احتلوا ارضنا ، وجحدوا حقنا ، وطغوا في البلاد وأكثروا فيها الفساد . اللهم فرد عنا كيدهم .. وفل حدهم .. ومزق جمعهم ... وخذهم ومن ناصرهم او اعانهم او هادنهم او وادهم اخذ عزيز مقتدر .. اللهم واجعل الدائرة عليهم .. وسق الوبال اليهم .. واذل دولتهم .. واذهب عن ارضك سلطانهم . ولا تدع لهم سبيلا على احد من المؤمنين .. )", "ولا شك ان تلكم المضايقات التي تعرض لها المستعمرون البريطانيون اقنعتهم بأن قاعدة القنال لم تعد صالحة لبقائهم .. وقد ساعد ذلك على تحسين موقف المفاوض المصري - فيما بعد - ، واجلاء القوات الاجنبية عن ارض الكنانة .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0077.png"}, {"n": 78, "paras": ["وفي عام ١٩٥٣ كانت الحركة الاسلامية الساعد الايمن للثورة التي اطاحت بالملك فاروق . وهذا ما ذكره عبد الناصر في مذكراته التي كتبها له الاستاذ حلمي سلام في مجلة المصور تحت عنوان ( حركة الجيش من المهد الى اللحد ) .. وقد أشار الى هذا كذلك انور السادات في مواضع مختلفة من كتابه ( اسرار الثورة المصرية ) منها قوله : وكنا نريد ان نفكر في التنفيذ العملي . فكان لا بد لنا من ان نعاود الاتصال بالاخوان ليكونوا هم القوة الشعبية التي تشاركنا باسم الشعب تبعات العمل الكبير (١) الى ان يقول : ( لقد أصبح الملك العوبة في يد الانجليز ، ولم يعد في استطاعتنا ان نعول عليه في شيء من خططنا . بل لعل من الاسلم ان نعتبره من الاعداء .. وهكذا ذهبت مع الاعداء صفوف الوفد وصفوف السعديين ولم يبق في الميدان الا قوة الاخوان (٢) .", "بعد حركة ٢٢ تموز قررت الحركة الاسلامية عدم الاشتراك في الحكم وآثرت الوقوف منه موقف الناصح الامين . ولقد عبر المرحوم الاستاذ حسن الهضيبي المرشد العام بقوله ( اننا نقف منهم موقف الناصح المتجرد نؤيدهم اذا أصابوا ونوجههم اذا أخطأوا .. ) .", "ثم جاءت الاتفاقية الأخيرة مع الانجليز الخاصة ( بقناة", "(١) اسرار الثورة المصرية بقلم انور السادات صفحة ٩٠", "(٢) اسرار الثورة المصرية صفحة ١٢١"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0078.png"}, {"n": 79, "paras": ["السويس ) ورأت الحركة الاسلامية فيها ربطا لمصر بعجلة الغرب ، واتجاها سياسيا خطيرا من شأنه ان يورط العالم العربي في آثاره ، واتفاقا ضمنيا على الدفاع المشترك .. فقدمت بذلك مذكرة رسمية الى قيادة الثورة قياما بواجب النصح . الا ان هذا التصرف لم يرق لرجال الثورة واعتبروا هذه البادرة تكريسا لوصاية الحركة الاسلامية عليهم ..", "وفي ( ١٣ كانون الثاني عام ١٩٥٤ ) أصدرت قيادة الثورة قرارا بحل الحركة الاسلامية على اعتبار انها حزب سياسي يسري عليها ما يسري على سائر الاحزاب السياسية .. وفي اواخر عام ١٩٥٤ اتهمت الحركة بالقيام بمحاولة قلب نظام الحكم . وزج برجالها وقادتها في المعتقلات والسجون .. وحكم على ستة منهم بالاعدام . وفي ١٣ ربيع الثاني ١٣٧٤ ه الموافق ٨ كانون الاول عام ١٩٥٤ نفذ حكم الاعدام بالرغم من استنكار العالم الاسلامي الشعبي والرسمي لهذه الاحكام ..", "من هم شهداء عام ١٩٥٤ والشهداء الستة هم :", "١ - الشهيد عبد القادر عوده - القانوني الكبير ، والعالم الفقيه ، وصاحب كتاب ( التشريع الجنائي في الاسلام ) والذي كان مقررا ان يظفر بجائزة فؤاد الاول للدراسات القانونية عام"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0079.png"}, {"n": 80, "paras": ["١٩٥١ لولا عبارتان اصر المؤلف على اثباتهما في الكتاب .. وهما تقريره ان الاسلام لا يعرف توارث الملك ولا يقر الا الاختيار والبيعة . وتقرير ه ان الاسلام لا يعترف لحاكم بأنه فوق القانون ..", "٢ - الشهيد الشيخ محمد فرغلي - العالم المجاهد والقائد البطل الذي اقترن اسمه بما يشبه الأساطير عند الانجليز . وكان اسمه يُسمع طوال الليل ايام الكفاح من محطة ( فايد ) للاذاعة البريطانية معلنة عن جائزة قدرها خمسة آلاف جنيه لمن يُرشد اليه حيا او ميتا ..", "٣ - الشهيد يوسف طلعت - التي كانت تسميه القيادة البريطانية في القنال ( بجزار الانجليز ) وهو احد افذاذ الرجال الذين قادوا المجاهدين في قتال الانجليز في مصر واليهود في فلسطين ..", "٤ - الشهيد المحامي ابراهيم الطيب", "٥ - الشهيد المحامي هنداوى دوير", "٦ - الشهيد محمود عبد اللطيف", "اسباب الخلاف", "قد لا تظهر لغير المطلعين على حقائق الامور العوامل الرئيسية التي فجرت الخلاف بين الحركة الاسلامية ورجال الثورة .. ومن الانصاف القول بأن الحركة الاسلامية لم يتأت"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0080.png"}, {"n": 81, "paras": ["لها من الوسائل الاعلامية ما تدافع بها عن نفسها، او تدفع بها ذلك السيل العرم من الشبهات والشائعات التي الصقت بها .. والحقيقة ان الخلاف بين الحركة الاسلامية والثورة خلاف عقيدي مبدئي ..", "فالحركة الاسلامية تؤمن بالاسلام قوة أساسية لنهضة العرب والمسلمين .. وتؤمن بضرورة تبني مبادئه وأحكامه في كل الخطوات الاصلاحية الاجتماعية والاقتصادية والسياسية .. والاعتماد على روحه الثائرة في وجه الاستعمار والصهيونية .. وترى في تبني ( المذاهب المادية ) وتطبيق ( الاشتراكية العلمية) سيرا على غير هدى ، وتخبطا بدون طائل ، واستنفادا للجهود واضاعة للزمن ، وطمسا لتراث الاسلام العظيم ، وتنكر ا لهذا الدين القيم . واحلالا لأستعمار مكان استعمار ..", "والحركة الاسلامية ترى ان معركة تحرير فلسطين هي المعركة الرئيسية التي يجب ان توجه اليها القوى وتحشد لها الجهود . وترى ان تأجيل المعركة ، او تحويلها منها الى غيرها ، او مسخها لا يخدم - في الحقيقة - الا اسرائيل ويعطيها فرصة التسلح والتمكن ، وبالتالي يعمل مع الزمن على تعقيد القضية ، ويفرض على العرب الرضوخ لسياسة الأمر الواقع .", "والحركة الاسلامية تؤمن بالحرية .. الحرية الشعبية في كل مظهر من المظاهر ، حيث يتسنى للشعب ان يعبر عن آرائه في شؤون بلاده بحرية واطمئنان . ومن ذلك حرية الصحافة والكتابة"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0081.png"}, {"n": 82, "paras": ["وترى في اضطهاد حرية الرأي وحرمان الشعب من حقه المقدس وكم الانفاس ومصادرة الحريات من شر ما تصاب به الامم وتنكب به الشعوب .. فهو تكريس للديكتاتورية والتسلط . وهذا ما تأباه طبيعة الاسلام ، وما حذر منه عمر بن الخطاب خليفة رسول الله صلى الله عليه وسلم بقوله ( لا خير فيكم ان لم تقولوها . ولا خير فينا ان لم نسمعها ) .", "وظلت الحركة الاسلامية منذ عام ١٩٥٤ ثابتة على هذه المواقف امينة على تلكم المبادىء برغم المحن الشديدة التي تعرضت لها وبرغم التنكيل الذي وقع بأفرادها ..", "محنة عام ١٩٦٥", "وفي مطلع عام ١٩٦٥ اتهمت الحركة الاسلامية مرة اخرى بالاعداد لقلب نظام الحكم . وملئت السجون والمعتقلات والواحات بعشرات الالاف من المواطنين .", "ومن غرائب هذه الحملة اتهام الحركة الاسلامية بأنها تنوي نسف المنشئات والكباري ومحطات الاذاعة ومراكز توليد الكهرباء واغتيال المطربين والمطربات والراقصات . كل ذلك من اجل استثارة الرأي العام ضد الحركة الاسلامية .. والربط باستمرار وبين الارهاب والاجرام ولطبع هذه الصورة الكريهة المنفرة في اذهان الناس ..", "الاسلام - ٦ - ٨١ -"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0082.png"}, {"n": 83, "paras": ["ومن غرائب هذه الحملة - كذلك - ان يساق الابرياء الى الموت من غير ان يسمح لهم بالدفاع عن أنفسهم . ويمنع حتى الدفاع عنهم من محامين كثيرين كانوا قد تطوعوا للدفاع .. وفي ٢١ آب ١٩٦٦ صدر الحكم بالاعدام على الداعية الاسلامي الكبير الاستاذ سيد قطب واثنين اخرين هما محمد يوسف هواش وعبد الفتاح اسماعيل . وفي صباح التاسع والعشرين من آب عام ١٩٦٦ كان صاحب ( الظلال ) في طريقه الى منصة الاعدام فرحا بلقاء ربه .. وفي الكون الفسيح صدى قصيدته العصماء زغاريد بهجة وأغاني اعراس للشهيد الجديد ..", "أخني ان ذرفت علي الدموع وبللت قبري بها في خشوع فأوقد لهم من رفاتي الشموع وسيروا بها نحو مجد تليد", "اخي ان نمت نلق احبابنا فروضات ربي اعدت لنا وأطيارها رفرفت حولنا فطوبى لنا في ديار الخلود", "أخي ستيد جيوش الظلام ويشرق في الكون فجر جديد فأطلق لروحك اشواقها ترى الفجر يرمقنا من بعيد", "(١) رائد الفكر الاسلامي الحديث وهو كاتب وشاعر واديب - وضع كتابه (العدالة الاجتماعية في الاسلام) عام ١٩٥٠ وفي عام ١٩٥٣ مثل مصر في حلقة الدراسات الاجتماعية الذي عقد في دمشق . وفي عام ١٩٥٥ حكم عليه بالسجن مدة خمسة عشر عاما مع الاشغال الشاقة . وفي عام ١٩٦٥ اعيد الى السجن وصدر عليه الحكم بالاعدام ."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0083.png"}, {"n": 84, "paras": ["لمحات من تاريخ الحركة السياسية في العراق : أما دور الحركة الاسلامية في العراق فلم يكن اقل أهمية من دورها في سائر الاقطار ..", "ففي عام ١٩٤٧ قاد الاستاذ محمد محمود الصواف مؤسس الحركة الاسلامية في العراق الجماهير الشعبية في بغداد ضد معاهدة ( بورتسموث ) الانكليزية العراقية حتى الغيت وأسقطت وفي عام ١٩٤٨ نظمت الحركة الاسلامية المظاهرات وعبأت القوى الشعبية ضد قرارات التقسيم التي اقرتها هيئة الامم المتحدة مما أدى الى اسقاط حكومة صالح جبر ..", "وعندما نشبت معركة فلسطين كان الصواف على الخطوط الامامية ينظم الجموع ويجند الجنود ويبث في النفوس روح الاقدام والتضحية .. وقد أسندت اليه الهيئات الشعبية حينذاك امانة سر جمعية انقاذ فلسطين .", "وفي عام ١٩٥٢ أصدرت الحركة الاسلامية مجلة ( الاخوة الاسلامية ) ونددت فيها بسياسة الحكومة الموالية للاستعمار البريطاني .. فكان ان عطلها ( نوري السعيد ) كما عطل جماعة الاخوة الاسلامية وصادر ممتلكاتها واعتقل قادتها وجرد بعضهم من وظائفهم ..", "وفي عام ١٩٥٨ عندما قامت ثورة ١٤ تموز كانت الحركة الاسلامية في طليعة الاتجاهات الشعبية التي دعمتها وأيدتها"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0084.png"}, {"n": 85, "paras": ["وساندتها .. وعندما انحرفت الثورة عن طريقها السوي تصدت الحركة الاسلامية لمكافحتها ومكافحة الاتجاه الشيوعي الذي يَسْنُدُها .. ولقد تعرضت الحركة الاسلامية - انذاك - لحملة مسعورة من الفوضويين والشيوعيين والمنحرفين عقب ثورة الموصل .. فهوجِمت المنازل .. ونهبت المكتبات .. وحطمت المطابع ودور النشر الاسلامية .. بل لقد بلغ الامر حد السحل في الشوارع لعدد من شباب الدعوة كان منهم : الشهيد هاشم عبد السلام .. الشهيد عبد الرازق شندالة .. الشهيد محمد البنا .. وغيرهم .", "لمحات من تاريخ الحركة الاسلامية في الاردن", "وفي الاردن سجلت الحركة الاسلامية صفحات مشرقة في تاريخ العرب السياسي .. ففي عام ١٩٤٨ اشترك شبابها في حرب فلسطين على طول الحدود .. ولا تزال الروابي الامامية في القدس وصور باهر وجينين ونابلس والخليل - تحتفظ بذكريات البطولة لهؤلاء المجاهدين الابرار .. وظلت الحركة الاسلامية في الاردن تواكب القضية الفلسطينية ، وتفضح المؤامرات المبيتة لها بدون هوادة ولا لين .. ففي عام ١٩٥٥ عندما اثار ( انتوني ايدن ) رئيس مجلس"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0085.png"}, {"n": 86, "paras": ["الوزراء البريطاني موضوع الاخذ بقرارات الامم المتحدة التي تقضي بتقسيم فلسطين هب رجال الحركة يُعلنون النكير ويفضحون النوايا الاستعمارية الخبيثة ..", "وقد جاء في البيان الذي اذاعته الحركة الاسلامية في ذلك الحين ما يلي : ( إن رأي الحركة الاسلامية في قضية فلسطين واضح صريح لا يحتمل ادنى معنى من معاني المواراة والمراوغة .. رأي الحركة التي حملت الارواح على الاكف ، وخاضت المعركة مدفوعة بايمان راسخ وعقيدة ثابتة .. وما زلنا نرى ان قضية فلسطين لا يحلها ( ايدن ) ولا يحلها ( ايزنهاور ) انما يحلها ( المسلمون ) الذين يضحون بأعز ما يملكون في سبيل الله .. )", "مقاومة كلوب والسياسة الانجليزية :", "أما على صعيد السياسة الداخلة فان مواقفهم الجريئة مع الاستعمار المتمثل يومذاك ( بكلوب وأعوانه ) من البريطانيين كان له اكبر الاثر في الهاب الجماهير وفي الغاء المعاهدة البريطانية اللعينة ..", "وقد تعرضت الحركة الاسلامية من جراء ذلك لحملات متلاحقة .. وفتحت السجون والمعتقلات الصحراوية للمجاهدين الذين قالوا للطاغية ( كلوب ) وهو في اوج سطوته ( انت سفاح انجليزي مخادع لا بد ان يكون لك نهاية .. )"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0086.png"}, {"n": 87, "paras": ["ولم يكتف ( كلوب ) بمطاردة دعاة الاسلام واعتقالهم .. بل وصل به الاجرام الى تعطيل جريدة ( الكفاح الاسلامي ) الناطقة بلسان الحركة الاسلامية في الاردن .. وطالب بوضع قانون يمنع المسلمين من التحدث والخطابة في المساجد الا بترخيص رسمي من الحكومة ..", "مقاومة الاحلاف الاجنبية :", "كان صوت الحركة الاسلامية في الاردن اول صوت ارتفع بالنكير على مقترحات ( تمبلر ) التي ترمي الى ادخال الاردن في ( حلف بغداد ) .. وقد قاومت الحركة الاسلامية هذه الفكرة مقاومة شديدة . وخرجت مظاهراتها في جميع انحاء البلاد تطالب الحكومة بتنفيذ رغبات الشعب وتجنيب الاردن الاحلاف الاجنبية ، مما حدا برجال الجيش والبوليس الى اطلاق النار على شرفة المركز العام للحركة الاسلامية في عمان ، بينما كان قادة الحركة يخطبون في جموع المتظاهرين .. ثم أعقب ذلك حملة اعتقالات واسعة لقادة الحركة وعلى رأسهم الاستاذ محمد عبد الرحمن خليفة وأودعتهم السجن .. ثم عادت فأفرجت عنهم بعد ان جرف تيار الشعب حكومة ( المجالي ) والقى بها خارج الحكم ..", "ويوم تعرض الاردن لضغط استعماري كي يقبل بمشروع ( ايزنهاور ) قاد زعماء الحركة المعركة من جديد . وقد جاء"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0087.png"}, {"n": 88, "paras": ["في بيان رسمي اذاعوه عام ١٩٥٨ : ( أيها الشعب الذي هزم ( تمبلر ) وحطم ( حلف بغداد ) وطرد الطاغية ( كلوب ) ببطولات خالدة .. انت مدعو اليوم لمقاومة مشروع ( ايزنهاور ) ..", "في وجه القوات البريطانية :", "وفي عام ١٩٥٨ يوم نزلت قوات بريطانية في الاردن عقب ثورة ١٤ تموز العراقية وأثناء الثورة اللبنانية ووصول الاسطول السادس الاميركي الى شواطيء لبنان وقفت الحركة الاسلامية بكل قواها تجابه هذه الاجراءات الاستعمارية ، مما حمل السلطة الحاكمة على الزج بقادتها في معتقل ( الجفر ) الصحراوي .. وهكذا تواصل الحركة الاسلامية بعين ساهرة كشف ما يبيته الاستعمار من مؤامرات لاخضاع الاردن للنفوذ الغربي واطماع اسرائيل ..", "من تاريخ الحركة السياسي في سوريا", "لم يكن في سوريا حتى مطلع القرن العشرين تيار اسلامي واضح المعالم .. وانما كانت هنالك دعوات دينية وطرق صوفية مقتصرة في دعوتها على بعض جوانب الاسلام.. وفي عام ١٩٣٣ شعر المرحوم ( الدكتور مصطفى السباعي )"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0088.png"}, {"n": 89, "paras": ["وكان حينئذ شابا يافعا بحاجة الاسلام الى جماعة تؤمن به وتحمله وتدافع عنه . فبدأ بدعوة الناس الى دين الله ، يبصرهم به ويجمعهم عليه . وفي عام ١٩٣٧ تأسس في حلب ( دار الارقم ) وفي دمشق ( الشبان المسلمون ) وفي حمص ( جمعية الرابطة ) وفي حماه ( الاخوان المسلمون ) وفي عام ١٩٤٤ كانت الحركة قد استكملت عدتها واتخذت شكلا تنظيميا واحدا في كل المدن السورية . وانتخب الاستاذ السباعي مراقبا عاما لها . وفي عام ١٩٤٨ حدثت كارثة فلسطين . وهب الشعب السوري يطالب بالتطوع للقتال . واخذت الحركة الاسلامية زمام المبادرة . وفتحت مراكز التطوع في كل مكان . ولما تم للحركة الاسلامية اعداد كتائبها خرجت بهم الى ارض الجهاد . وكان من نصيبها الدفاع عن بيت المقدس اولى القبلتين وثالث الحرمين الشريفين . وكان القتال يدور فيها من بيت الى بيت ومن شارع لشارع . ولقد ابلى المجاهدون بلاء حسنا . وسقط منهم عشرات الشهداء اودع اكثرهم الثرى بجوار المسجد الاقصى منهم : الشهيد ضيف الله مراد - الشهيد تيسير طه - الشهيد محمد عينوص - الشهيد محمد عرنوس - الشهيد محمود دندشي الشهيد محمد قباني - الشهيد نايف حسن عودة - الشهيد"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0089.png"}, {"n": 90, "paras": ["راضي الجوهري - الشهيد محمد طالب - الشهيد محمد صباغ وفي ميدان الاصلاح السياسي لعبت الحركة الاسلامية في سوريا دورا هاما .. فدعت اول الى اقامة حكم صالح يزيل عن سوريا مخلفات الاستعمار .. ووجهت النصح الى الحكومات الوطنية المتعاقبة . وقاومت كل انحراف في في الحكم والادارة . ولم تجامل في ذلك رئيسا ولا حكومة ولا زعيما .. وحاربت الحركة مشروع سوريا الكبرى لانه مشروع استعماري يجعل من سوريا نقطة ارتكاز للنفوذ الغربي في الوطن العربي . وفي عام ١٩٤٩ ساهمت في انتخابات ( الجمعية التأسيسية ) ونجح عدد من رجالها واشتركوا في وضع ( الدستور ) وصبغوه بالصبغة الاسلامية ... وفي عهد اديب الشيشكلي عام ١٩٥٢ تعرضت الحركة لمضايقات شديدة وفرضت الرقابة على قادتها وسرح الدكتور السباعي من عمله في الجامعة السوريه ، ثم نفي من البلاد .. وفي عام ١٩٥٨ كانت الحركة الاسلامية في طليعة الحركات التي ايدت ( الوحدة الثنائية ) بين مصر وسوريا .. ويوم تجمعت الفئات الحزبية كلها في ( نادي الضباط ) بدمشق لتوقيع وثيقة الانفصال كانت الحركة الاسلامية الوحيدة التي رفضت بموضوعية واصرار .. واستطاعت الحركة الاسلامية في هذه الفترة ان تستقطب تأييد القوى الشعبية"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0090.png"}, {"n": 91, "paras": ["كلها ، وتكوّن تيارا اسلاميا قويا ظهرت نتائجه في أول انتخابات نيابية بعد الانفصال عام ١٩٦١ . وفي اعقاب حركة الثامن من آذار التي اطاحت بالعهد الانفصالي تعرضت الحركة ولا تزال تتعرض لمحن متلاحقة على يد الحزب الحاكم في سوريا . وفي عام ١٩٦٤ توفى مؤسس الحركة الاسلامية الدكتور مصطفى السباعي مخلفا وراءه تراثا اسلاميا ضخما من الكتب والمؤلفات وحركة اسلامية هي امل سوريا اليوم . ومن مؤلفات السباعي : السنة ومكانتها في التشريع الاسلامي - الاحوال الشخصية - المرأة بين الفقه والقانون احكام الصيام وفلسفته - احكام الاهلية والوصية - احكام المواريث - الوصايا والفرائض - مشروعية الارث في الاسلام - نظام السلم والحرب في الاسلام - اخلاقنا الاجتماعية- ومجلة حضارة الاسلام التي لا تزال تصدر حتى اليوم .", "كلمة اخيرة :", "واخيرا فان الحركة الاسلامية الحديثة التي كان لها فضل السبق في ميدان الجهاد ، ومقاومة اعداء الاسلام في الداخل والخارج ، والتي قدمت خلال نصف قرن من الزمن قوافل متلاحقة من شهدائها الابرار . جديرة بأن يُزاح عن تاريخها"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0091.png"}, {"n": 92, "paras": ["المشرق ستارُ الاباطِل وتُبدّدُ عن امجادها حُجُب الدس والافتراء .. لقد مرت بالامة فترةٌ سوداءُ قائمة تمكن فيها اعداء الاسلام بما يملكون من وسائل الدعاية والاعلام ، تمكنوا من خداع الجماهير وتضليل الرأى العام .. تمكنوا من قذف المؤمنين الابرياء وتشوية سُمعة المجاهدين الاتقياء الاتقياء .. تمكنوا من وسمهم بشتى التُهم والاراجيف دون ان يراعوا في ذلك إلا ولا ذمة ودونما خوفٍ من الله المنتقم الجبار .. لقد حارب الاسلام ودعاته اعداءُ الاسلام في الشرق والغرب في الداخل والخارج .. حاربهم الاستعمار متجمعا .. وحاربتهم الاقطاعية متكتلة .. وحاربتهم الرأسمالية طاغية .. وحاربتهم الشيوعية متجنية .. وحاربهم الفساد والشر والطغيان في كل مكان ..", "واصبح من واجب الجماهير المسلمة ان تعرف ( الحركة الاسلامية ) على حقيقتها ، فلا تنخدعَ بعد اليوم بدعايات المغرضين ووشايات الحاقدين ( كبرت كلمةً تخرج من افواههم ان يقولون الا كذبا ) واخيرا فليعلم المسلمون في شتى ديارهم وأقطارهم ان الحرب على الحركة الاسلامية هي في حقيقتها حربٌ على الاسلام نفسه .. وان اعداء الاسلام من الملحدين والشيوعيين والغربيين واتباعهم واشياعهم مصممون على اختلاق كل"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0092.png"}, {"n": 93, "paras": ["مبرر لضرب الحركة الاسلامية ليصلوا من وراء ذلك الى ضرب الاسلام .. والاغرب من كل هذا قيام بعض المحسوبين على الاسلام في بلاد الاسلام بالترويج لهذه الاتجاهات الهدامة وتأييدها ومناصرتها بل والباسها ثوب الاسلام ، والاسلام منهم ومنهابراء .. لقد هان الاسلام على الناس الى درجة انهم اصبحوا في شك من كل ما يتصف بالاسلام أو يحمل اسمه . وهذا ما جهد للوصول اليه اعداء الله منذ زمن بعيد .. واخيرا .. فان الصراع المصيري الذي يخوضه الاسلام مع القوى المادية العاتية والحركات الشعوبية الحاقدة ليس الا صورة مصغرة عن التأمر الذي استقطب معاول الهدم في الشرق والغرب والذي لا يهدف سوى استئصال الوجود الحركي للاسلام .. ومن هنا يتحتم على المسلمين - كل المسلمين تحديد موقفهم من هذا الصراع .. فان لم يكونوا في صف الاسلام فقد وقفوا في صف اعدائه .. وإننا نعيذهم بالله ان يكونوا عونا لأعداء الاسلام واعداء الله . ونذكرهم بقول الله عز من قائل ( الم تر الى الذين تولوا قوما غضب الله عليهم ، ما هم منكم ولا منهم ويحلفون على الكذب وهم يعلمون ) (استحوذ عليهم الشيطان فانساهم ذكر الله ، اولئك حزب الشيطان ، الا ان حزب الشيطان هم الخاسرون . ان"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0093.png"}, {"n": 94, "paras": ["ان الذين يحادّون الله ورسوله اولئك في الاذلين . كتب الله لأغلبنّ انا ورسلي ان الله قوي عزيز . لا تجدُ قوما يؤمنون بالله اليوم الاخر يوادّون من حادّ الله ورسوله ولو كانوا آباءهم او ابناءهم او اخوانهم او عشيرتهم . اولئك كتبَ في قلوبهم الايمان ، وايدهم بروح منه ويدخلهم جنات تجري من تحتها الأنهارُ خالدين فيها . رضي الله عنهم ورضوا عنه . اولئك حزب الله الا إن حزب الله هم المفلحون . )"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0094.png"}, {"n": 95, "paras": ["فصل في أحكام المرتد", "المرتد هو الذي يقطع الإسلام بنية أو قول كفر أو فعل، سواء كان استهزاء أو عناداً أو اعتقاداً.", "ومن أتى بناقض من نواقض الإسلام، وجب عليه التوبة فوراً، والرجوع إلى الإسلام بالشهادتين، والإقلاع عما وقع فيه من كفر.", "قال الله تعالى: ﴿وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِ فَيَمُتْ وَهُوَ كَافِرٌ فَأُولَٰئِكَ حَبِطَتْ أَعْمَالُهُمْ فِي الدُّنْيَا وَالْآخِرَةِ ۖ وَأُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ﴾.", "فالردة تحبط العمل، وتوجب الخلود في النار إن لم يتب العبد منها قبل الموت.", "ومن أحكام المرتد:", "١- بطلان عقده للنكاح، فلا يحل له أن يمسك زوجته المسلمة أو الكتابية.", "٢- لا يرث ولا يورث، فلا يرث من أقاربه المسلمين، ولا يرثه أقاربه المسلمون.", "٣- لا يغسل ولا يصلى عليه ولا يدفن في مقابر المسلمين إذا مات على ردته.", "والواجب على ولي الأمر أو من ينوب عنه دعوة المرتد إلى التوبة، وإزالة الشبهة التي قد تكون عرضت له، فإن أصر على كفره، أقيم عليه حد الردة."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0095.png"}, {"n": 96, "paras": ["الانقلابية بَيْنَ الإِسْلَامِ وَالِاتِّجَاهَاتِ الْحَدِيثَةِ"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0096.png"}, {"n": 97, "paras": ["فصل في أحكام المرتد", "المرتد هو الذي يقطع الإسلام بنية أو قول كفر أو فعل، سواء كان استهزاء أو عناداً أو اعتقاداً.", "ومن أتى بناقض من نواقض الإسلام، وجب عليه التوبة فوراً، والرجوع إلى الإسلام بالشهادتين، والإقلاع عما وقع فيه من كفر.", "قال الله تعالى: ﴿وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِ فَيَمُتْ وَهُوَ كَافِرٌ فَأُولَٰئِكَ حَبِطَتْ أَعْمَالُهُمْ فِي الدُّنْيَا وَالْآخِرَةِ ۖ وَأُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ﴾.", "فالردة تحبط العمل، وتوجب الخلود في النار إن لم يتب العبد منها قبل الموت.", "ومن أحكام المرتد:", "١- بطلان عقده للنكاح، فلا يحل له أن يمسك زوجته المسلمة أو الكتابية.", "٢- لا يرث ولا يورث، فلا يرث من أقاربه المسلمين، ولا يرثه أقاربه المسلمون.", "٣- لا يغسل ولا يصلى عليه ولا يدفن في مقابر المسلمين إذا مات على ردته.", "والواجب على ولي الأمر أو من ينوب عنه دعوة المرتد إلى التوبة، وإزالة الشبهة التي قد تكون عرضت له، فإن أصر على كفره، أقيم عليه حد الردة."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0097.png"}, {"n": 98, "paras": ["ان ظواهر الانقلابية السياسية والفكرية والعسكرية تسود العصر الحديث .. ففي كل قطر من اقطار آسيا وافريقيا واميركا اللاتينية مظهر من مظاهر الثورة والتمرد على اركان الوجود التقليدي ..", "والمنطقة العربية ، تعيش منذ عام ١٩٤٨ ازمة استقرار في حياتها الداخلية وعلاقاتها الخارجية ، بسبب ما مر بها من اضطرابات وما تتابع عليها من احداث ..", "لقد عانت هذه المنطقة من الانتكاسات في ماضيها وحاضرها ما دمر فيها الروح المعنوية وعاد بالخراب والبؤس على حياتها الاجتماعية والاقتصادية والسياسية .. ان عدم تركيز المفاهيم على فلسفة حياة صحيحة جعل كل المحاولات ( الانقلابية ) هامشية وسطحية وجانبية .. ذلك ان كل محاولة اصلاحية لا تقدم حلولا جذرية للقضايا التي فشلت سابقتها", "الاسلام - ٧"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0098.png"}, {"n": 99, "paras": ["في حلها ، ستعمل - حتما - على تعقيد هذه القضايا وبالتالي ستتسبب في نشوء مشكلات جديدة وخطيرة ..", "ان النقطة التي تنطلق منها كل مشكلاتنا وتتأثر بها جميع اوضاعنا ، هي اننا - حتى الآن - من تجاربنا الكثيرة المتلاحقة لم نعرف من نحن وماذا نريد؟؟", "ان ( رايشنبخ ) يقرر في دراساته ، بأن التقدم الفكري يجد مكانه اولا في الاسئلة التي وضعها المفكرون ، وفي القضايا التي طرحها الفلاسفة للبحث ، وليس في الاجوبة .. فالسؤال الصحيح هو مفتاح كل تطور صحيح ..", "وامتنا - في عصرها الحديث - يجب ان تطرح على نفسها سؤالين اثنين .. من انا ؟ وماذا اريد ؟", "والجواب على هذين السؤالين ينبغي ان يصدرا - بعمق - عن شخصية هذه الامة وخصائصها وعن تراثها العقيدي والفكري والاخلاقي ..", "اما الاجوبة التي تفرض على الامة فرضا وهي لا تمثل شخصيتها ، ولا تعبر عن اصالتها ، فستكرس الدوران في حلقة مفرغة من التجارب الفاشلة المدمرة .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0099.png"}, {"n": 100, "paras": ["جهل وتضليل :", "ظل الاعتقاد السائد لدى جمهور المسلمين ان الاسلام دين تعبدي لا علاقة له في شؤون الحياة الفكرية والاجتماعية والاقتصادية والسياسية حتى قيام ( الحركة الاسلامية ) وظهور الوعي الاسلامي في العصر الحديث ..", "فالعالم الاسلامي بسبب من تأثره بالحضارة الغربية ولوثاتها الجائحة اعتبر خروج اوروبا والعالم الغربي على الكنيسة وحده من نفوذها السياسي ، بل وفصله السلطة الاكليرية عن السلطة الزمنية ، منولا ينبغي النسج عليه ، وقاعدة عامة يجب الصدور عنها في فصل الدين - عن الدولة ، وجعل ما لقيصر لقيصر وما لله لله", "وبسبب من جهل المسلمين - كذلك - بخصائص دينهم وآفاق شريعتهم .. وبانتقال القيادة الفكرية والسياسية منهم الى غيرهم .. وبانتقاض الحكم الاسلامي في العهد العثماني والذي كان على علاته ومساوئه مظهرا للحاكمية الاسلامية والوجود السياسي للاسلام ..", "بأسباب من هذه وغيرها اصبح تصور المسلمين وفهمهم للاسلام لا يتفق وجوهر هذا الدين وحقيقته في شيء ."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0100.png"}, {"n": 101, "paras": ["الاسلام منهج انقلابي :", "وعندما قامت الحركة الاسلامية في مطلع القرن العشرين تمسح عن الدين ركام الجهل والتضليل كانت حريصة غاية الحرص على معالجة هذه المشكلة بادىء بدء ، وتركيز الصورة الاسلام الصافية الصحيحة في الاذهان ..", "فالاسلام منهج حياة .. هكذا يجب ان يفهم .. وهكذا يجب ان يطبق .. وهو ثورة وانقلاب .. ثورة لا تقتصر على جانب من جوانب الحياة وانما تمتد الى كل جانب .. وانقلاب لا تعبر عنه ( كلمة او شعار ) بل هو تحويل ( كيفي ) للمجتمع وتغيير ( جذري ) لقواعده واصوله .", "فالانقلاب الاسلامي لا يتحقق بتغيير نظام او تعديل دستور .. و لا يتم برفع راية واذاعة بيان .. وانما يتحقق ويتم باستكمال المقومات والفعاليات والخصائص الاسلامية في شخصية الامة .. يتم ( بقوامة ) النهج الالهي ( وحاكميته ) للمجتمع .. وبالتالي تقويم التصورات - كل التصورات .. وخضوع التصرفات - كل التصرفات - لهذه القوامة والحاكمية.", "خصائص الانقلابية الاسلامية :", "لهذا كانت ( انقلابية ) الاسلام شاقة وتتطلب الكثير من الكفايات والجهود . فالانقلابية الاسلامية تختلف في"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0101.png"}, {"n": 102, "paras": ["خصائصها وطبيعتها عن سائر ( الحركات الانقلابية ) . واهداف الانقلابية الاسلامية غير اهداف الانقلابية الحزبية والسياسية والعسكرية .. وما تستسيغه هذه قد يمجّه ذوق الاسلام ويأباه .. فالاسلام نسيج وحده في ( تصوره العقيدي ) وفي ( تخطيطه الانقلابي )", "الكلية", "ان الاسلام في جزئياته وكلياته في احكامه واصوله وتشريعاته مبدأ وجداني .. فهو يحرص اشد ما يحرص على تحريك عوامل الخير في اعماق النفس البشرية ، واقامة رقابة ساهرة تقي الانسان غوائل الالتواء والانحراف ..", "والاسلام ليس مجرد نظام من النظم لا يتجاوز في مداه الاصلاحي الانقلابي دائرة الشؤون الاجتماعية والاقتصادية والسياسية .. وانما هو بحكم طبيعته منهج كلي وشامل .. وهذا ما يجعل انقلابيته متفردة في النهج والاسلوب ..", "فالانقلاب الاسلامي لا يمكن تحقيقه بطرق متصنعة مرتجلة ، ولا بخطط عسكرية خاطفة ، بل لا بد لذلك من عوامل ومقومات يتحقق بها تغيير الاسس الفكرية والخلقية والثقافية والنفسية التي يقوم عليها المجتمع الجاهلي ..", "العقائدية :", "وعقائدية الاسلام هي التي تحدد طبيعته الانقلابية وترسم"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0102.png"}, {"n": 103, "paras": ["بالتالي مناهجه ومخططاته . فالاطار الذي يحدد به الاسلام ميدان العمل الاسلامي يرتكز على دعامتين اساسيتين : أولا : سلامة الغاية التي يستهدفها روح العمل الاسلامي والتي لا تعتد بها مقاييس الانقلابية الحزبية والسياسية والعسكرية ثانيا : سلامة الوسيلة وضمان مشروعيتها وموافقتها لروح الاسلام حتى تتحقق صيانة الانقلاب الاسلامي من كل انتكاس او ارتكاس .. فالاسلام لا يعتبر الوصول الى الحكم ( غاية ) بل وسيلة لأقامة امر الله وتنفيذ حاكميته .. فاذا كان الوصول الى الحكم لا يضمن تحقيق هذه الغاية فهو وعدمه سواء ... الانسانية : ومفهوم ( الانقلابية ) في الاسلام كذلك - مفهوم انساني لا يسلك الى الخير سبيل الشر ، ولا يدعو الى الفضيلة بلسان الرذيلة ، ولا يشيد البناء بالجماجم والدماء .. فبينما يهدد ( تكاتشف ) الزعيم الشيوعي بابادة وافناء كل الروس الذين تجاوزوا الخمسة والعشرين لأنهم غير قابلين لتمثيل الافكار الماركسية ، يطالعنا الاسلام بمواقفه الانسانية الكريمة في معاملة الاخرين ( عندما فتح المسلمون مكة . اتى ابو بكر بأبيه يقوده - وكان لا يزال مشركا - .. فلما رآه الرسول صلى الله عليه وسلم"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0103.png"}, {"n": 104, "paras": ["قال .. هلا تركت هذا الشيخ في بيته حتى اكون انا الذي آتيه فيه .. فقال ابو بكر - يا رسول الله هو احق ان يمشي اليك من ان تمشي - انت اليه .. فأجلسه الرسول بين يديه ، ثم مسح على صدره وقال له اسلم فأسلم )", "بهذا تكون انقلابية الاسلام .. انسانية في خصائصها اخلاقية في طبيعتها .. عقائدية في وسائلها وغاياتها ..", "الانقلابية في مفهوم الاتجاهات الاخرى", "في المفهوم الشيوعي", "تعتمد ( الانقلابية ) في الحركة الشيوعية اول ما تعتمد على دفعة الاحقاد التي تستثيرها وتذكيها في نفوس العمال والكادحين ، وبالتالي على بث روح الانتقام والتشفي بين طبقات المجتمع الواحد كسبيل لقيام الثورة العمالية وتحقيق الانقلاب الشيوعي .. والى هذه الغاية يوجه ماركس خطابه للعمال فيقول ( سيكون عليكم ان تجتازوا خمسة عشر عاما او عشرين او خمسين من الحروب الاهلية بين الشعوب لكي تصبحوا اهلا للسلطة السياسية ) - (١) وهذا ما نصت عليه الفقرة الشيوعية التالية ( وبالتالي فالانتقال من الرأسمالية", "(١) كارل ماركس - كشف الستار عن محاكمة الشيوعيين في كولوني"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0104.png"}, {"n": 105, "paras": ["الى الاشتراكية وتحرير الطبقة العاملة من النير الرأسمالي يمكن تحقيقها لا بتغييرات بطيئة ولا باصلاحات ، بل بتغيير كيفي للنظام الرأسمالي فقط ، أي بالثورة (١)", "وتعتمد ( الانقلابية ) في الحركة الشيوعية على وسائل العنف والقسر في سبيل تحقيق اهدافها وغاياتها .. ويبدو هذا جليا وواضحا في معظم بياناتها وكتبها . يقول لينين : ( ان الثورة البروليتارية غير ممكنة بدون تحطيم جهاز الدولة البورجوازي بالعنف وابداله بجهاز جديد (٢) ويقول ( بابون) اذبحوا المستبدين والاشراف والمليون المذهبين . ويقول ( برودون ) : ( يجب على العالم ان يدرك مرة واحدة واخيرة بأن ليس من علاج ضد الارستقراطية سوى الافناء )", "ولعل في الوسائل الحقيرة الملتوية التي تعتمدها الشيوعية في تحقيق الانقلاب الماركسي ما يبين الفرق الشاسع بين طبيعتها وطبيعة الاسلام الانقلابية .. يقول لينين : ( يجب على المناضل الشيوعي ان يتمرس بشتى ضروب الخداع والغش والتضليل .. فالكفاح من اجل الشيوعية يبارك كل وسيلة تحقق الشيوعية .. يجب ان يكون مفهوما ان الشيوعية غاية نبيلة .. وان تحقيق الغاية النبيلة يتطلب في كثير من الاحيان", "(١) المادية الدياليكتيكية صفحة ٢٥", "(٢) الثورة البروليتارية - المجلد ٢٣ صفحة ٢٤٢"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0105.png"}, {"n": 106, "paras": ["استخدام وسائل غير نبيلة .. ولهذا فان الشيوعية تبارك شتى الوسائل المناهضة للاخلاق ما دامت هذه الوسائل تساعد على تحقيق اهدافنا الشيوعية .. ) الانقلابية في مفهوم الثورة الفرنسية : والثورة الفرنسية التي كانت انتفاضة في وجه الظلم الاجتماعي والاستبداد السياسي اتبعت وسائل غير شريفة ومخالفة كل المخالفة للشعارات والمبادىء التي رفعتها .. يقول ( مارا ) ما هذا الظلم ؟ من هو الذي لا يستطيع ان يشهد بأنني اريد قطع الرؤوس حبا بخلاص الكثيرين .. ويحرض ( لوثر ) الناس لإخماد الثورة الفرنسية فيقول : ( من يستطيع ، فليقتل ، فليخلق ، فليذبح سرا او علانية .. اذن فاقتلوا واذبحوا واخنقوا ما طاب لكم هؤلاء الفلاحين الثائرين .. ) الانقلابية في مفهوم البروتوكولات الصهيونية : والحركة الصهيونية تسوغ كل الفظائع والمفاسد واساليب المكر والخداع من اجل قيام ( مملكة يهوذا ) وانشاء ( الدولة اليهودية العالمية ) ويكفينا ان ننقل بعض الفقرات والمقاطع من ( بروتوكولات حكماء صهيون ) (١) لنتبين طبيعة ( المفهوم الانقلابي ) في الحركة الصهيونية ..", "(١) كتاب الخطر اليهودي ( بروتوكولات حكماء صهيون ) تاليف محمد خليفة التونسي"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0106.png"}, {"n": 107, "paras": ["من فقرات البروتوكول الاول", "( ان السياسة لا تتفق مع الاخلاق في شيء ( .. والحاكم المقيد بالاخلاق ليس بسياسي بارع ، وهو لذلك غير راسخ على عرشه .. ولا بد لطالب الحكم من الالتجاء الى المكر والرياء . فان الشمائل الانسانية العظيمة من الاخلاص والامانة تصير رذائل في السياسة . وانها تبلغ في زعزعة العرش اعظم مما يبلغه الد الخصوم )", "( ان الغاية تبرر الوسيلة . وعلينا . ونحن نضع خططنا الا نلتفت الى ما هو خير واخلاقي بقدر ما نلتفت الى ما هو ضروري ومفيد .. )", "( يجب ان يكون شعارنا ( كل وسائل العنف والخديعة ) .. ان هذا الشر هو الوسيلة الوحيدة للوصول الى هدف الخير .. لذلك يتحتم الا نتردد لحظة واحدة في اعمال الرشوة والخديعة والخيانة اذا كانت تخدمنا في تحقيق غايتنا ..", "من فقرات البروتوكول الثالث", "( ينبغي ان نحكم الطوائف باستغلال مشاعر الحسد والبغضاء التي يؤججها الضيق والفقر . وهذه المشاعر هي وسيلتنا التي نكتسح بها بعيدا كل من يصدوننا عن سبيلنا ). ( وحينما يأتي اوان تتويج حاكمنا ( العالمي ) سنتمسك"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0107.png"}, {"n": 108, "paras": ["بهذه الوسائل نفسها ، اي نستغل الغوغاء كيما نحطم كل شي قد يثبت انه عقبة في طريقنا .. )", "من فقرات البروتوكول السابع", "( في كل اوروبا وبمساعدة اوروبا - يجب ان ننشر في سائر الاقطار الفتنة والمنازعات والعداوات المتبادلة . فان في هذا فائدة مزدوجة : فاما اولا - فبهذه الوسائل سنتحكم في اقدار كل الاقطار التي تعرف حق المعرفة ان لنا القدرة على خلق الاضطرابات كما نريد .. واما ثانيا - فبالمكايد والدسائس سوف نصطاد جميع الحكومات .. ولكي نصل الى هذه الغايات يجب علينا ان ننطوي على كثير من الدهاء والخبث..)", "من فقرات البروتوكول الحادي عشر", "( ان الامميين غير اليهود كقطيع من الغنم .. واننا الذئاب فهل تعلمون ما تفعل الغنم حينما تنفذ الذئاب الى الحظيرة ؟؟ انها لتغمض عيونها عن كل شيء .. والى هذا المصير سيندفعون . فسنعدهم بأننا سنعيد اليهم حرياتهم بعد التخلص من اعداء العالم .. ولست في حاجة الى اخبركم الى متى سيطول بهم الانتظار حتى ترجع اليهم حرياتهم الضائعة ؟)"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0108.png"}, {"n": 109, "paras": ["من وقائع الانقلابية العربية", "والبلاد العربية شهدت في السنوات العشر الماضية وقائع واحداث ( انقلابية ) اقل ما يقال فيها انها دنيئة وخسيسة وانها ( لا عقائدية ولا اخلاقية ولا انسانية )", "كانت كل الحركات الانقلابية ( الوطنية ، والقومية ، والشعوبية ، والاشتراكية ، والشيوعية ) عطشى للدماء ، للقتل ، للسحل ، لهدر الكرامات ، لاستباحة الاعراض ، للتمثيل بالجثث ، ولحرق الاحياء ؟؟", "فماذا يقال عن ( انقلابات ) تعمد الى الرؤوس فتقطعها ، والى الاجساد فتمزقها ، والى البطون فتبقرها ، والى الجماجم فتهشمها ؟", "لقد دلت الارقام والحقائق ان هناك مئات القتلى دفنوا بدون مبرر ، وبدون محاكمة ، بل من جراء التعذيب المبرح في مكاتب التحقيق ، ومقرات ( الحرس القومي ) ؟؟", "ان الوصف لهذه الاحداث والوقائع يبقى مجرد كلمة لا تعطي الصورة الحقيقية لمن اراد الوصول الى تصور رقمي صحيح وكامل ..", "ان هذه الاتجاهات الانقلابية المنحرفة تدور جميعها في حلقات مفرغة من المآسي والمجازر البشرية الرهيبة .. في حين تحتاج الامة الى وضع يضمن لها الاستقرار والاطمئنان ويزيل"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0109.png"}, {"n": 110, "paras": ["عن نفسها كابوس البؤس الجاثم فوقها .. وضع سليم صحيح لا يفرض بالحديد والنار ولا بالمدافع والدبابات .. وضع تحميه نفوس الناس وتحرسه قلوب الجماهير .. وهذا الوضع لن يتحقق الا بالاسلام وبالانقلاب الاسلامي ...", "الاهداف الكبرى لانقلابية الاسلام", "رأينا فيما تقدم كيف ان الاسلام ينفرد بمفهومه الانقلابي عن سائر الاتجاهات والحركات الحزبية والسياسية والعسكرية. وان الغاية التي يسعى اليها الاسلام لا تبرر استخدام وسائل منحرفة لا توافقها في المضمون والجواهر .. وفيما يلي سنعرض لبعض الاهداف التي تحققها انقلابية الاسلام ..", "في المجال العقيدي", "فالعقيدة هي المرآة التي تنعكس عليها شخصية الامة واخلاقها ومبادئها .. وكلما كانت هذه المرآة صافية رقراقة كانت شخصية الامة خلاقة معطاءة .. وهذا ما جعل الاسلام يهتم اول ما يهتم بتركيز التصور العقيدي السليم في اذهان الناس .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0110.png"}, {"n": 111, "paras": ["كانت انقلابية الاسلام العقيدية التي اطاحت بأصنام ( الجاهلية ) تهدف الى اعلان العبودية المطلقة لله .. ولم تكن هذه الحملة العقيدية الكبرى التي قام بها الاسلام مقتصرة على تحطيم ( الصنمية الحجرية البدائية ) التي تمثلت في ( اللات وهبل ) وانما تجاوزتها الى تحطيم أي لون من الوان الصنمية ، سواء كانت صنمية بشرية ام صنمية مادية ، وبالتالي الى هدم معابدها في القلوب وازالة معالمها من النفوس ..", "وواقعنا الحديث وان كان يعاني كثيرا من المعضلات .. الا انه يشكو في رأس هذه المشكلات جميعا داء خبيثا طاغيا يتمثل في انحراف تصوره العقيدي او انعدامه ..", "ومظاهر الانحراف العقيدي في عصرنا الحاضر متبدية في صورتين اساسيتين ..", "صورة تمثل اسفاف التصور العقيدي المترتب عن انكار وجود الله وسائر العوامل الغيبية .. وتتبدى هذه الصورة في مظاهر الالحاد التي تكرسها المذاهب المادية والنظرية الدياليكتيكية ...", "وصورة تمثل انحراف التصور العقيدي المتأتي عن طغيان ( الحاكمية ) الفردية ( والتاليه ) البشري .. وهما نتيجة من النتائج الحتمية التي يكرسها سوء التصور الاسلامي وبالتالي ضعف الوازع الايماني ..", "ان المجتمع البشري يعيش انحرافا عقيديا خطيرا .. وان"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0111.png"}, {"n": 112, "paras": ["سوء اوضاعه ( الاخلاقية والاجتماعية والاقتصادية والسياسية) هي في الحقيقة انعكاس طبيعي لهذا ( الخواء العقيدي ) الذي خلفته الحضارة الغربية واصلته الفلسفة الماركسية .. ان جميع المقدرات ( العلمية ، والمادية ، والفنية ، وغيرها ) من فائض الابداع المادي لم تتمكن من توفير الطمأنينة والاستقرار في هذا المجتمع .. واحساس الانسان بجوعه النفسي والروحي آخذ في الازدياد يوما بعد يوم .. ذلك ان حياته المجدبة اصبحت تسير سيراً ( آليا ) مملا لا يفقه له معنى ، غير ما يراه امامه من مرئيات تروح وتجيء في طلب الرزق ، وتأمين مطالب الجسد ..", "لهذا حرص الاسلام - من اول الطريق - على حل هذه المشكلة حلا جذريا ، يتذوق معه الانسان طعما جديداً لهذه الحياة .. فيدرك الغاية من وجوده على الارض ويدرك ( القدرة الحقيقية ) التي اوجدته .. انه لم يخلق عبثاً .. ولم تخلقه المادة الصماء .. وهو لم يوجد صدفة في هذه الاكوان .. بل أن الله خلقه بقدرته، ونفخ فيه من روحه ، واسجد له ملائكته ، وجعل له السمع والبصر والفؤاد .. . وسخر له ما في البر والبحر .. وجعل بقاءه في الدنيا مرهونا بما قدر له من اجل كما جعل مصيره في الآخرة بما قدمه من عمل .", "تلك هي عقيدة الاسلام التي تربط الانسان الضائع بقوة الله وبمنهج الله وبالخط الذي رسمه الله في هذه الحياة حين"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0112.png"}, {"n": 113, "paras": ["قال (وان هذا صراطي مستقيما فاتبعوه ولا تتبعوا السبل فتفرق بكم عن سبيله ذلكم وصاكم به لعلكم تتقون .. )", "في المجال الاخلاقي", "ان نقطة الخلاف الرئيسية بين المنهج الاسلامي وسائر النظم الحديثة ، انه مبدأ أخلاقي وانها نظم مادية غير اخلاقية . ومن هذه النقطة بالذات تنشأ سائر المضاعفات وتتكاثر مختلف الاضداد بين طبيعة الانقلاب الاسلامي واهدافه وبين طبائع الانقلابات الاخرى واهدافها ..", "فالانقلاب الاسلامي حين اوضح الغاية التي جاء لتحقيقها كان صريحا مع طبيعته الاخلاقية الى ابعد حدود الصراحة ( انما بعثت لأتمم مكارم الاخلاق .. )", "والاخلاقية في الاسلام ليست نظاما خاصا ، او مجموعة تعاليم ومثل منفصلة عن اجزاء المنهج الاسلامي كما قد يظن كثير من الناس .. وانما هي معطيات خيرة وروح كريمة تنساب في كل جانب من جوانب هذا المنهج ..", "ومن هنا كانت اخلاقية الانقلاب الاسلامي تعني ارساء القيم الانسانية الرفيعة في كل ناحية من نواحي الحياة اجتماعية كانت ام اقتصادية ام سياسية .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0113.png"}, {"n": 114, "paras": ["فالحكم الاسلامي .. لا يقوم على ( الشورى ) ارضاء لخواطر الشعب ، وتملقاً لعواطف الجمهور .. بل لأن الشورى مبدأ اخلاقي وسواه من انظمة الحكم ( مبادىء لا اخلاقية ) كالتسلط والتحكم والديكتاتورية ..", "والاسلام حين ينادي ( بالعدالة الاجتماعية ) فلا يطرح بها شعارا للدعاية والمتاجرة والاستهلاك او ليستميل بها العمال والكادحين .. بل لأنه يرى في الظلم الاجتماعي والنظام الرأسمالي ظواهر غير اخلاقية مدمرة ..", "والاسلام حين يعلن ( المساواة الانسانية ) بين البشر اجمعين بيضهم وسودهم ، عربهم وعجمهم فلا يفعل ذلك حرصاً على تأييد الملونين والمستضعفين بل لأن في التمييز العنصري والتفاوت الطبقي بواعث ( لا اخلاقية )", "وهكذا ترتسم اخلاقية الاسلام في جميع مبادئه ونظمه وتشريعاته .. ومن هنا كانت اخلاقية المنهج الاسلامي ترفض رفضا قاطعا جميع الوسائل والطرق الانقلابية غير الاخلاقية .. فالمؤامرات والثورات والانقلابات التي تعتمد على الاغتيال والقتل والتدمير والاكراه ، اساليب وحشية لا ترضى عنها اخلاقية الاسلام وتأباها طبيعته الانسانية السمحة ..", "الاسلام - ١١٣ -"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0114.png"}, {"n": 115, "paras": ["في المجال الفكري والتشريعي", "لم تقتصر انقلابية الاسلام على ربط الضمير الانساني بالله عز وجل عن طريق ( العقيدة ) .. او على ارساء القيم الانسانية عن طريق ( الاخلاق ) .. وانما رافق ذلك كله انقلاب في التفكير والتصور شمل كل ناحية من نواحي الحياة ، الفردية والجماعية ، الداخلية والخارجية ، التوجيهية والتشريعية ..", "وكانت الثورة الانقلابية التي اعلنها الاسلام على الفكر الجاهلي عنيفة شعواء .. بدأها بتنظيف العقل البشري من الوهم والخرافة ، وتحرير التصور الانساني من كل ما يلوث صفاءه ونقاءه ..", "كان الفكر العربي قبل الاسلام محدود الآفاق ، قبلي النزعة . خلا بعض اللفتات الانسانية التي عرض لها الشعر الجاهلي مما لا يمكن اعتبارها بحال من خصائص الفكر الجاهلي . وانما هي مظهر من مظاهر التأثر بمخلفات النصرانية واليهودية والفلسفات القديمة ..", "لقد عملت انقلابية الاسلامية على الخروج بالفكر العربي من عزلته وانطوائيته ، وعلى ايقاظ الوعي الاجتماعي والسياسي في الحياة العربية ..", "فالمفهوم السياسي عند العرب كان يقوم على اعتبار ( القبيلة ) هي الوحدة السياسية .. وكانت العصبية هي الرابطة التي تجمع"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0115.png"}, {"n": 116, "paras": ["بين افرادها او العشائر المنتمية اليها .. فحرص الانقلاب الاسلامي على مكافحة هذه النزعة وبث روح الانفتاح .. تمهيدا لأعلان اول وحدة سياسية وعقيدية في حياة الناس .. فكان من اثار هذا الانقلاب الفكري الذي حققه الاسلام ان اصبح العرب يعتبرون التضامن والاتحاد واجبا مقدسا تمليه اصرة الدين الجديد .. وبينما كانت علاقتهم السياسية مبنية على ثارات الجاهلية اذا بالاسلام يمسح عن هذه العلائق كل ما يشوبها ، ويسكب فيها من روح الاخوة والالفة ما جعلها امتن العلائق واقواها وجعل الوحدة الاسلامية ارسخ الوحدات واعمقها .. ( واعتصموا بحبل الله جميعا ولا تفرقوا ، واذكروا نعمة الله عليكم اذ كنتم اعداء فالف بين قلوبكم فأصبحتم بنعمته اخوانا .. )", "وأما المفهوم الاجتماعي عند العرب فلم يكن اسلم من مفهومهم السياسي .. واذا كانت العصبية القبلية عنوان حياتهم السياسية فان النزعة الطبقية والعنصرية ميزة حياتهم الاجتماعية . حتى بلغ التفاوت الطبقي عندهم حدا لا يوصف .. فعمد الاسلام فورا على اذابة هذه الفوارق الاجتماعية وتحرير الارقاء والعبيد واشاعة روح المساواة على ضوء القاعدة الاسلامية الكريمة (ايها الناس—ان ربكم واحد.. وان اباكم واحد .. كلكم لآدم وآدم من تراب .. اكرمكم عند الله اتقاكم .. ليس لعربي على عجمي ولا لعجمي على عربي"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0116.png"}, {"n": 117, "paras": ["ولا لأحمر على ابيض ، ولا لأبيض على أحمر فضل الا بالتقوى . ) ويكفي انقلابية الاسلام اثرا في حياة العرب الاقتصادية انها ارست اسس التكافل الاجتماعي والمادي . ووضعت من النظم والتشريعات ما يحقق العدالة الاجتماعية والرخاء .. فاذا بالمجتمع العربي الجاهلي الذي كان يئن من الفاقة والعوز ويتكفف فارس والروم .. اذا بهذا المجتمع تتدفق فيه الخيرات وتعمه البحبوحة والرفاه ويأتيه الرزق رغدا من كل مكان ..", "الخطة الانقلابية", "إذا كان الاسلام منهجا انقلابيا فان تحقيق هذا المنهج يتطلب تجمعا حركيا انقلابيا .. أي ان الحركة التي تتصدر للعمل الاسلامي ينبغي ان تكون في مستوى تحقيق الانقلاب الاسلامي وعيا ونهجا وكفاية . ان الحركة الاسلامية احوج ما تكون الى تخطيط انقلابي تبلغ به مرحلة التنفيذ العملي لأهدافها ومبادئها .. واعني بالتخطيط الانقلابي « نظرية الحركة واسلوبها في تغيير واقع انساني قائم بآخر منشود .. بكل ما يقتضيه ذلك من فهم شامل ودقيق للواقع القائم ، وتقدير واع للقوى والعوامل التي تحركه .. وتصور عميق للواقع الاسلامي المنشود ، ومدى ما يحتاجه من كفايات وامكانيات »."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0117.png"}, {"n": 118, "paras": ["وينبغي ان يكون في مضمون خطة الانقلاب الاسلامي حرص الحركة الاسلامية على ان تتولى هي بنفسها تحقيق منهجها في الحكم الاسلامي .. وليس من الاخلاص والتجرد في شيء - كما يتصور البعض - زهدها في تولي الحكم .. ذلك ان العالم والتاريخ لا يعرفان حركة على الاطلاق قدمت عصارة نضالها وكفاحها لغير المؤمنين بأهدافها الملتفين معها فكريا وعقيديا واخلاقيا وسياسيا .. فالثورة الفرنسية كانت امنية من الاماني التي عمل لها روسو وفولتير ومنتسكيو .. والانقلاب الشيوعي كان ثمرة المخطط الذي وضعه ماركس ولينين .. والنازية الالمانية لم تظهر الا في ارض غزاها هيجل وفيخته وغوته ونيتشيه ..", "الطليعة المؤمنة", "ان الخطة ( الانقلابية ) التي اعتمدها رسول الله صلى الله عليه عليه وسلم كانت غاية في الدقة والاحكام .. ولا اظن الحركة الا بالغة اهدافها ومحققة غاياتها ان هي التزمت نفس الطريق .. كان العنصر الرئيسي والاساسي في خطة الانقلاب الاسلامي الاول يتمثل في اعداد ( الطليعة المؤمنة ) المرشحة لحمل تبعات العمل والتنفيذ .. اعدادها نفسيا ومعنويا واخلاقيا .. واعدادها فكريا وعمليا .. واعدادها ايمانيا وجهاديا .. للقيام بالدور الكبير .."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0118.png"}, {"n": 119, "paras": ["والحركة الاسلامية - في العصر الحديث - ان لم تعبىء في اولى مراحلها ( مخزون ) الكفاح للمدى الطويل ، فستستنفد قوتها بسرعة وفي اول الطريق .. وتكون بذلك قد اصابت الاسلام مقتلا وحكمت على نفسها بالاعدام ..", "ان الاسلام ليحتاج في هذه الفترة الى ( طليعة ) على مستوى جيد من الاعداد والتكوين .. طليعة نذرت نفسها لهذا الدين .. طليعة راسخة العقيدة والايمان ، ثابتة القلب والجنان .. طليعة سامية الخلق ، عميقة الادراك ، ماضية العزيمة .. طليعة تعيش الاسلام بكل وجودها وتمنحه كل وجودها . ومثل هذه الفئة لا يمكن ان تصنعها الاجواء العاطفية والمناورات السياسية كما لا يمكن ان تخلقها المناهج السطحية والعفوية ، ان لم تكن قد صاغتها العقيدة ونسجت جوانب شخصيتها مبادىء الاسلام واخلاقه ومثله ..", "ولو لم تكن طليعة الاسلام في عهد النبوة على هذا المستوى من الاعداد لما قامت للاسلام قائمة ولما خطت دعوته خطوة واحدة الى الامام فضلا عن بلوغها اطراف المعمورة .", "لقد استنفدت مرحلة التكوين من حياة النبوة ما لم يستنفده عمل اخر .. ولكنها اسفرت في النهاية عن حصيلة مباركة امدت الحركة الاسلامية بأفذاذ الرجال مدى طويلا من الزمن"], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0119.png"}, {"n": 120, "paras": ["المناخ المناسب", "واذا كانت خطة الانقلاب الاسلامي في عهد النبوة قد حرصت اشد الحرص على اعداد الطليعة الاسلامية .. فانها قد حرصت كذلك وبعد ذلك على انتقاء المناخ المناسب والمكان الصالح لقيام الانقلاب الاسلامي ..", "وهذه البادرة من الرسول صلى الله عليه وسلم لفتة الى اللامركزية في العمل الاسلامي .. واشارة الى ان اقامة الحكم الاسلامي قد يكون سهلا وممكنا في مكان وصعبا ومستحيلا في آخر .. وعندها يصبح من الضروري افراغ الجهد فيما هو ممكن وميسور حفاظا على الطاقات والاوقات من الضياع والبوار ..", "وهذا المعنى بالذات يفرض وجود وحدة تخطيط للعمل الاسلامي في العصر الحديث .. من شأنه ان يوجه نشاط التجمعات الحركية جمعاء ويعمل على صب الجهد حيث ينفع الجهد ، وتعبئة القوى حيث يقدر النجاح ، وتمكين الغرس حيث يؤمل الاثمار ..", "ان هذه تذكرة فمن شاء اتخذ الى ربه سبيلا قد بلغت اللهم فاشهد ."], "img": "../../../_ocr-work/libocr/yakan-islam-fikra/pages/0120.png"}]};
